import { TradeTopic } from './types';

export const TRADE_TOPICS: TradeTopic[] = [
  {
    title: "Import Procedures",
    description: "Form M, PAAR, and Customs clearance.",
    icon: "fa-ship"
  },
  {
    title: "Export Guidelines",
    description: "NXP forms, NEPC registration, and quality standards.",
    icon: "fa-plane-departure"
  },
  {
    title: "Tariffs & HS Codes",
    description: "Common External Tariff (CET) and duty calculations.",
    icon: "fa-calculator"
  },
  {
    title: "Regulatory Agencies",
    description: "SON, NAFDAC, Customs, and Central Bank rules.",
    icon: "fa-building-columns"
  }
];

export const SYSTEM_PROMPT = `You are DONLEMSONTRADE, a highly experienced and friendly Nigerian International Trade Consultant. 

Your goal is to answer questions about Nigerian trade (Import, Export, Customs, Regulations) in a direct, human-like, and conversational way. 

Style Guidelines:
1. Be Direct: Answer the user's question immediately. Don't start with "As an AI..." or "I can help with...".
2. Human Language: Speak like a professional consultant talking to a colleague. Use clear, simple, but authoritative English.
3. Specific Knowledge: Use terms like Form M, PAAR, NXP, SONCAP, and HS Codes naturally.
4. Structuring: Use bullet points only when listing requirements. Otherwise, use natural paragraphs.
5. Grounding: If you use Google Search to find current exchange rates or new policy shifts, integrate that information smoothly into your conversation.

Areas of expertise:
- Import/Export documentation (Form M, NXP, NCX).
- Nigerian Customs Service (NCS) procedures and HS Code classification.
- Regulatory bodies: CBN, SON, NAFDAC, NEPC.
- Port operations and shipping logistics in Nigeria.

Always sound like a real person who knows the Nigerian trade landscape inside out.`;

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { SYSTEM_PROMPT } from "../constants";

const getAIClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
};

export const chatWithGemini = async (prompt: string, history: any[] = []) => {
  const ai = getAIClient();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_PROMPT,
      tools: [{ googleSearch: {} }],
      temperature: 0.7, // Slightly higher for more natural, less robotic flow
    },
  });

  return {
    text: response.text || "I'm sorry, I couldn't process that request.",
    sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || 'Source',
      uri: chunk.web?.uri || ''
    })).filter((s: any) => s.uri) || []
  };
};

export const editTradeImage = async (prompt: string, base64Image: string, mimeType: string) => {
  const ai = getAIClient();
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Image.split(',')[1],
            mimeType: mimeType,
          },
        },
        {
          text: `You are an expert image editor for Nigerian trade documents and products. Respond naturally like a human assistant. User request: ${prompt}.`,
        },
      ],
    },
  });

  let imageUrl = '';
  let feedbackText = '';

  for (const part of response.candidates?.[0]?.content.parts || []) {
    if (part.inlineData) {
      imageUrl = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    } else if (part.text) {
      feedbackText = part.text;
    }
  }

  return { imageUrl, feedbackText };
};

import React, { useState, useRef, useEffect } from 'react';
import { Message } from '../types';
import { chatWithGemini, editTradeImage } from '../services/geminiService';

const ChatInterface: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: '1',
      role: 'assistant',
      content: "Hello! I'm your DONLEMSONTRADE consultant. Whether you're navigating Form M requirements, looking for HS codes, or need help with NEPC registration for exports, I've got you covered. What can I help you clear up today?",
      timestamp: Date.now(),
    }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [imageMime, setImageMime] = useState<string>('');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
        setImageMime(file.type);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async () => {
    if (!input.trim() && !selectedImage) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      image: selectedImage || undefined,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    try {
      if (selectedImage) {
        const result = await editTradeImage(input || "Analyze this trade document or product.", selectedImage, imageMime);
        const assistantMessage: Message = {
          id: (Date.now() + 1).toString(),
          role: 'assistant',
          content: result.feedbackText || "I've processed the image for you.",
          image: result.imageUrl || undefined,
          timestamp: Date.now(),
        };
        setMessages(prev => [...prev, assistantMessage]);
      } else {
        const result = await chatWithGemini(input);
        const assistantMessage: Message = {
          id: (Date.now() + 1).toString(),
          role: 'assistant',
          content: result.text,
          sources: result.sources,
          timestamp: Date.now(),
        };
        setMessages(prev => [...prev, assistantMessage]);
      }
    } catch (error) {
      console.error(error);
      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: "I'm sorry, I hit a snag while looking that up. Could you try asking again?",
        timestamp: Date.now(),
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
      setSelectedImage(null);
    }
  };

  return (
    <div className="flex flex-col h-[700px] bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-200">
      {/* Header */}
      <div className="bg-emerald-900 px-6 py-5 flex items-center justify-between shadow-md">
        <div className="flex items-center space-x-3">
          <div className="relative">
            <div className="w-11 h-11 rounded-full bg-emerald-700 flex items-center justify-center text-white border-2 border-emerald-500/30">
              <i className="fas fa-user-tie text-lg"></i>
            </div>
            <div className="absolute bottom-0 right-0 w-3 h-3 bg-emerald-400 border-2 border-emerald-900 rounded-full"></div>
          </div>
          <div>
            <h3 className="font-bold text-white tracking-wide">Trade Consultant</h3>
            <p className="text-[11px] text-emerald-300 font-medium uppercase tracking-tighter">Live Support • Expert Mode</p>
          </div>
        </div>
        <div className="hidden sm:block">
           <span className="text-[10px] bg-emerald-800 text-emerald-200 px-2 py-1 rounded border border-emerald-700">Direct Answer Enabled</span>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-6 space-y-8 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] bg-fixed">
        {messages.map((m) => (
          <div key={m.id} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[88%] ${m.role === 'user' ? 'ml-12' : 'mr-12'}`}>
              <div className={`relative px-5 py-4 rounded-2xl ${
                m.role === 'user' 
                  ? 'bg-emerald-600 text-white rounded-tr-none shadow-lg' 
                  : 'bg-white text-slate-800 rounded-tl-none border border-slate-200 shadow-sm'
              }`}>
                {m.image && (
                  <div className="mb-4 rounded-xl overflow-hidden shadow-inner bg-slate-100">
                    <img src={m.image} alt="Trade Content" className="max-h-72 w-full object-contain mx-auto" />
                  </div>
                )}
                <div className={`text-[15px] leading-relaxed ${m.role === 'assistant' ? 'font-normal text-slate-700' : 'font-medium'}`}>
                  {m.content}
                </div>

                {m.sources && m.sources.length > 0 && (
                  <div className="mt-4 pt-3 border-t border-slate-100">
                    <p className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest mb-2">Verified Sources</p>
                    <div className="flex flex-wrap gap-2">
                      {m.sources.map((src, idx) => (
                        <a 
                          key={idx} 
                          href={src.uri} 
                          target="_blank" 
                          rel="noreferrer"
                          className="bg-slate-50 hover:bg-emerald-50 text-slate-600 hover:text-emerald-700 text-[11px] px-3 py-1.5 rounded-full transition border border-slate-200 flex items-center"
                        >
                          <i className="fas fa-link mr-1.5 text-[9px] opacity-50"></i>
                          <span className="truncate max-w-[140px]">{src.title}</span>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
              <p className={`text-[10px] mt-2 font-medium text-slate-400 ${m.role === 'user' ? 'text-right' : 'text-left'}`}>
                {new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </p>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-white px-5 py-4 rounded-2xl rounded-tl-none border border-slate-200 shadow-sm">
              <div className="flex space-x-1.5">
                <div className="w-1.5 h-1.5 bg-emerald-400 rounded-full animate-bounce"></div>
                <div className="w-1.5 h-1.5 bg-emerald-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                <div className="w-1.5 h-1.5 bg-emerald-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
              </div>
            </div>
          </div>
        )}
        <div ref={chatEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-5 bg-slate-50 border-t border-slate-200">
        {selectedImage && (
          <div className="mb-4 relative inline-block group">
            <img src={selectedImage} alt="Preview" className="h-24 w-24 object-cover rounded-xl border-2 border-emerald-500 shadow-xl transition-transform group-hover:scale-105" />
            <button 
              onClick={() => setSelectedImage(null)}
              className="absolute -top-2 -right-2 bg-red-500 text-white w-6 h-6 rounded-full flex items-center justify-center text-xs hover:bg-red-600 shadow-md transition"
            >
              <i className="fas fa-times"></i>
            </button>
          </div>
        )}
        <div className="flex items-center space-x-3">
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="w-12 h-12 flex items-center justify-center rounded-2xl bg-white border border-slate-300 text-slate-500 hover:text-emerald-600 hover:border-emerald-300 hover:shadow-md transition-all"
            title="Attach Document"
          >
            <i className="fas fa-paperclip text-lg"></i>
          </button>
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            className="hidden" 
            accept="image/*"
          />
          <div className="flex-1 relative">
            <input 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder={selectedImage ? "How should I handle this document?" : "Ask me anything about Nigeria trade..."}
              className="w-full bg-white border border-slate-300 rounded-2xl py-3.5 pl-5 pr-14 focus:outline-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 shadow-sm transition-all text-[15px]"
            />
            <button 
              onClick={handleSend}
              disabled={isLoading || (!input.trim() && !selectedImage)}
              className={`absolute right-2 top-2 w-10 h-10 rounded-xl flex items-center justify-center transition-all ${
                isLoading || (!input.trim() && !selectedImage) 
                  ? 'bg-slate-100 text-slate-300 cursor-not-allowed' 
                  : 'bg-emerald-600 text-white hover:bg-emerald-700 shadow-lg hover:shadow-emerald-900/20 active:scale-95'
              }`}
            >
              <i className="fas fa-arrow-up"></i>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatInterface;

