                </button>
              </div>

              <h4 className="font-black text-blue-900/40 mb-5 uppercase text-[10px] tracking-[0.3em] flex items-center">
                <span className="w-8 h-[1px] bg-blue-100 mr-3"></span> Complete Learning Path
