        const timestamp = new Date().toLocaleString();
        const content = `DONLEMSONTRADE GLOBAL COLLEGE - ${course.title}\n\nModules:\n${course.modules.join('\n')}\n\nGenerated: ${timestamp}`;
        const blob = new Blob([content], { type: 'text/plain' });
        const url = window.URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `Syllabus_${course.title.replace(/\s+/g, '_')}.txt`;
        link.click();
      } finally {
        setIsDownloading(false);
      }
    }, 1000);
