              <div className="mt-8 pt-6 border-t border-gray-100 flex gap-4">
                <button onClick={() => setSelectedCourse(null)} className="flex-1 bg-gray-50 text-gray-500 font-black text-xs uppercase py-4 rounded-2xl">Close</button>
                {enrolled.includes(selectedCourse.id) ? (
                   <button onClick={() => { startLesson(selectedCourse, 0); setSelectedCourse(null); }} className="flex-[2] bg-emerald-600 text-white font-black text-xs uppercase py-4 rounded-2xl shadow-lg">Start Learning</button>
