                  <button onClick={() => { handleEnroll(selectedCourse.id); setSelectedCourse(null); }} className="flex-[2] bg-blue-900 text-white font-black text-xs uppercase py-4 rounded-2xl shadow-lg shadow-blue-900/10 hover:bg-emerald-600 transition-all">Enroll Now</button>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </section>
  );
};

