        </div>

        {/* Course Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {displayedCourses.map(course => (
            <div key={course.id} className="bg-white border border-gray-200 rounded-2xl overflow-hidden shadow-sm flex flex-col hover:shadow-xl transition-all group">
              <div className="relative h-48 overflow-hidden">
                <img src={course.thumbnail} alt={course.title} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                <div className="absolute top-4 left-4 bg-white/90 backdrop-blur px-3 py-1 rounded-full text-[10px] font-bold text-blue-900 uppercase">{course.category}</div>
              </div>
              <div className="p-6 flex-1 flex flex-col">
                <h3 className="font-bold text-blue-900 text-lg mb-2 group-hover:text-emerald-600 transition-colors">{course.title}</h3>
                <p className="text-[11px] text-gray-400 font-bold uppercase mb-4 flex items-center">
                  <i className="fas fa-user-tie mr-2 text-emerald-500"></i> {course.instructor}
                </p>
                <div className="mt-auto pt-4 border-t border-gray-100 flex items-center justify-between">
                  <button onClick={() => setSelectedCourse(course)} className="text-[11px] font-bold text-blue-900 hover:text-emerald-600 uppercase tracking-widest transition">Curriculum</button>
                  {enrolled.includes(course.id) ? (
                    <button onClick={() => startLesson(course, 0)} className="bg-emerald-600 text-white px-5 py-2.5 rounded-xl text-xs font-bold hover:bg-emerald-700 transition-all shadow-md shadow-emerald-500/10">Start Learning</button>
                  ) : (
                    <button onClick={() => handleEnroll(course.id)} className="bg-blue-900 text-white px-5 py-2.5 rounded-xl text-xs font-bold hover:bg-blue-800 transition-all shadow-md shadow-blue-900/10">Enroll Now</button>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Full Screen Learning Experience */}
      {activeLesson && (
        <div className="fixed inset-0 z-[200] bg-white flex flex-col animate-in slide-in-from-bottom duration-500">
          <div className="bg-blue-900 px-6 py-4 text-white flex items-center justify-between shadow-xl">
            <div className="flex items-center space-x-6">
              <button onClick={() => setActiveLesson(null)} className="w-10 h-10 rounded-full hover:bg-white/10 flex items-center justify-center transition">
                <i className="fas fa-times"></i>
              </button>
              <div>
                <h2 className="font-bold text-sm tracking-tight">{activeLesson.course.title}</h2>
                <div className="flex items-center space-x-3 mt-1">
                  <div className="w-32 h-1.5 bg-blue-800 rounded-full overflow-hidden">
                    <div 
                      className="h-full bg-emerald-400 transition-all duration-700" 
                      style={{ width: `${((activeLesson.moduleIndex + (showQuiz ? 1 : 0.5)) / activeLesson.course.modules.length) * 100}%` }}
                    ></div>
                  </div>
                  <span className="text-[10px] text-blue-300 font-bold uppercase tracking-widest">
                    {showQuiz ? 'Assessment Phase' : `Topic ${activeLesson.moduleIndex + 1} of ${activeLesson.course.modules.length}`}
                  </span>
                </div>
              </div>
            </div>
            <div className="hidden md:flex items-center space-x-4">
               <div className="bg-white/10 px-4 py-2 rounded-xl flex items-center space-x-2">
                  <i className="fas fa-robot text-emerald-400 text-xs"></i>
                  <span className="text-[10px] font-black uppercase tracking-widest text-white/80">AI Instructor: Dr. Leo Donlems</span>
               </div>
            </div>
          </div>

          <div className="flex-1 flex overflow-hidden">
            {/* Sidebar Modules */}
            <div className="hidden lg:block w-80 border-r border-gray-100 bg-slate-50 overflow-y-auto p-8">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] mb-8 flex items-center">
                <i className="fas fa-stream mr-2"></i> Course Journey
              </h3>
              <div className="space-y-3">
                {activeLesson.course.modules.map((mod, i) => (
                  <button 
                    key={i}
                    onClick={() => !isLessonLoading && !isQuizLoading && startLesson(activeLesson.course, i)}
                    className={`w-full text-left p-4 rounded-2xl text-xs font-bold flex items-center space-x-4 transition-all border ${
                      activeLesson.moduleIndex === i 
                      ? 'bg-white border-emerald-200 shadow-lg shadow-emerald-500/5 text-blue-900' 
                      : 'text-gray-400 border-transparent hover:bg-white hover:text-gray-600'
                    }`}
                  >
                    <span className={`w-7 h-7 rounded-lg flex items-center justify-center shrink-0 ${
                      activeLesson.moduleIndex > i ? 'bg-emerald-500 text-white' : 
                      activeLesson.moduleIndex === i ? 'bg-blue-900 text-white' : 'bg-gray-200'
                    }`}>
                      {activeLesson.moduleIndex > i ? <i className="fas fa-check text-[10px]"></i> : i + 1}
                    </span>
                    <span className="leading-snug">{mod}</span>
                  </button>
                ))}
              </div>
            </div>

            {/* Content & Interaction Zone */}
            <div className="flex-1 overflow-y-auto bg-white p-8 md:p-16">
              <div className="max-w-3xl mx-auto">
                {isGraduated ? (
                  /* GRADUATION SCREEN */
                  <div className="text-center py-20 bg-emerald-50 rounded-[40px] border border-emerald-100 shadow-inner px-8">
                    <div className="w-28 h-28 bg-emerald-500 text-white rounded-full flex items-center justify-center text-5xl mx-auto mb-10 animate-bounce shadow-2xl">
                      <i className="fas fa-award"></i>
                    </div>
                    <h1 className="text-5xl font-black text-blue-900 mb-6 tracking-tighter">Certified Professional</h1>
                    <p className="text-blue-800/60 font-medium mb-12 max-w-md mx-auto text-lg leading-relaxed">Excellent work, {user}! You have mastered all components of {activeLesson.course.title}.</p>
                    <div className="flex flex-col md:flex-row items-center justify-center gap-6">
                      <button 
                        onClick={downloadCertificate}
                        className="w-full md:w-auto bg-blue-900 text-white px-12 py-5 rounded-3xl font-black uppercase tracking-widest text-xs hover:bg-blue-800 transition-all shadow-2xl active:scale-95"
                      >
                        Claim My Certificate <i className="fas fa-file-contract ml-2"></i>
                      </button>
                      <button 
                        onClick={() => setActiveLesson(null)}
                        className="w-full md:w-auto text-blue-900/40 font-black text-xs uppercase tracking-widest hover:text-blue-900 transition"
                      >
                        Return Home
                      </button>
                    </div>
                  </div>
                ) : showQuiz ? (
                  /* QUIZ INTERFACE */
                  <div className="animate-in fade-in slide-in-from-right duration-500">
                    <div className="flex flex-col md:flex-row md:items-center justify-between mb-12 gap-4">
                       <div className="flex items-center space-x-4">
                          <span className="bg-emerald-500 text-white px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest">Mastery Assessment</span>
                          <span className="text-blue-900/20 font-bold">/</span>
                          <span className="text-blue-900 text-xs font-extrabold uppercase tracking-widest">Question {currentQuizStep + 1} of 3</span>
                       </div>
                       <div className="text-xs font-bold text-emerald-600 bg-emerald-50 px-3 py-1 rounded-lg">
                         Current Score: {quizScore} / 3
                       </div>
                    </div>

                    <div className="mb-12">
                      <h2 className="text-3xl font-black text-blue-900 leading-tight tracking-tight">
                        {quizQuestions[currentQuizStep].question}
                      </h2>
                    </div>

                    <div className="grid grid-cols-1 gap-4">
                      {quizQuestions[currentQuizStep].options.map((option, i) => (
                        <button 
                          key={i}
                          onClick={() => handleAnswer(i)}
                          className="w-full text-left p-6 rounded-3xl border-2 border-slate-100 hover:border-emerald-500 hover:bg-emerald-50 transition-all group flex items-center justify-between bg-slate-50/50"
                        >
                          <div className="flex items-center space-x-6">
                            <span className="w-10 h-10 rounded-2xl bg-white border border-slate-200 flex items-center justify-center font-black text-blue-900 group-hover:bg-emerald-500 group-hover:text-white transition-all">
                              {String.fromCharCode(65 + i)}
                            </span>
                            <span className="text-slate-700 font-bold text-lg group-hover:text-emerald-900">{option}</span>
                          </div>
                          <i className="fas fa-chevron-right text-slate-200 group-hover:text-emerald-300 transition-all"></i>
                        </button>
                      ))}
                    </div>
                  </div>
                ) : (
                  /* LESSON CONTENT */
                  <div className="animate-in fade-in duration-700">
                    <div className="mb-10">
                      <span className="text-[10px] font-black text-emerald-600 uppercase tracking-[0.4em] mb-3 block">Now Teaching</span>
                      <h1 className="text-4xl font-black text-blue-900 tracking-tighter leading-none mb-4">{activeLesson.course.modules[activeLesson.moduleIndex]}</h1>
                      <div className="h-1.5 w-20 bg-emerald-500 rounded-full"></div>
                    </div>

                    {isLessonLoading ? (
                      <div className="space-y-8 animate-pulse">
                        <div className="h-4 bg-slate-100 rounded-full w-3/4"></div>
                        <div className="h-4 bg-slate-100 rounded-full"></div>
                        <div className="h-4 bg-slate-100 rounded-full w-5/6"></div>
                        <div className="h-4 bg-slate-100 rounded-full w-2/3"></div>
                        <div className="pt-20 flex flex-col items-center">
                           <div className="w-14 h-14 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                           <p className="mt-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">Professor is generating lesson content...</p>
                        </div>
                      </div>
                    ) : (
                      <div className="prose prose-slate prose-lg max-w-none text-slate-700 leading-relaxed font-medium">
                        <div className="whitespace-pre-wrap mb-16 lesson-text">{lessonContent}</div>

                        <div className="p-10 bg-blue-50 rounded-[40px] border border-blue-100/50 flex flex-col md:flex-row items-center justify-between gap-8 shadow-sm">
                          <div>
                            <h4 className="font-black text-blue-900 text-xl tracking-tight mb-2">Ready for Assessment?</h4>
                            <p className="text-sm text-blue-700 font-semibold opacity-70">Complete the mastery quiz to unlock the next trade module.</p>
                          </div>
                          <button 
                            onClick={generateQuiz}
                            disabled={isQuizLoading}
                            className="w-full md:w-auto bg-blue-900 text-white px-10 py-4 rounded-2xl font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center shadow-2xl hover:bg-emerald-600 transition-all active:scale-95"
                          >
                            {isQuizLoading ? (
                              <>
                                <i className="fas fa-sync fa-spin mr-3"></i>
                                Generating Quiz...
                              </>
                            ) : (
                              <>
                                <i className="fas fa-spell-check mr-3"></i>
                                Start Mastery Quiz
                              </>
                            )}
                          </button>
                        </div>
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Curriculum Preview Modal */}
      {selectedCourse && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-blue-900/60 backdrop-blur-md">
          <div className="bg-white w-full max-w-lg rounded-[32px] shadow-2xl overflow-hidden border border-white/20 animate-in zoom-in-95">
            <div className="bg-blue-900 p-10 text-white relative">
              <button onClick={() => setSelectedCourse(null)} className="absolute top-8 right-8 text-white/40 hover:text-white transition"><i className="fas fa-times text-xl"></i></button>
              <div className="flex items-center space-x-3 mb-4">
                 <span className="bg-emerald-500 text-[10px] font-black uppercase px-3 py-1 rounded-full">College Curriculum</span>
              </div>
              <h3 className="font-black text-3xl tracking-tighter leading-tight">{selectedCourse.title}</h3>
            </div>
            <div className="p-10">
              <div className="space-y-5 mb-10 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar">
                {selectedCourse.modules.map((mod, i) => (
                  <div key={i} className="flex items-center text-sm font-bold text-blue-900 space-x-4 group">
                    <span className="w-8 h-8 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center text-[10px] font-black border border-blue-100 group-hover:bg-emerald-500 group-hover:text-white transition-all shrink-0">{i+1}</span>
                    <span className="leading-snug">{mod}</span>
                  </div>
                ))}
              </div>
              <div className="flex gap-4">
                <button onClick={() => setSelectedCourse(null)} className="flex-1 bg-slate-50 text-slate-400 font-black text-xs uppercase tracking-widest py-5 rounded-2xl hover:bg-slate-100 transition">Cancel</button>
                {enrolled.includes(selectedCourse.id) ? (
                   <button onClick={() => { startLesson(selectedCourse, 0); setSelectedCourse(null); }} className="flex-[2] bg-emerald-600 text-white font-black text-xs uppercase tracking-widest py-5 rounded-2xl shadow-xl hover:bg-emerald-700 transition-all">Start Course</button>
                ) : (
                  <button onClick={() => { handleEnroll(selectedCourse.id); setSelectedCourse(null); }} className="flex-[2] bg-blue-900 text-white font-black text-xs uppercase tracking-widest py-5 rounded-2xl shadow-xl hover:bg-emerald-600 transition-all">Enroll Now</button>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </section>
  );
};

export default GlobalCollege;

import React, { useState, useEffect } from 'react';
import { TRADE_COURSES } from '../constants';
import { Course } from '../types';
import { chatWithGemini } from '../services/geminiService';

interface QuizQuestion {
  question: string;
  options: string[];
  correctAnswer: number;
}

const GlobalCollege: React.FC = () => {
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [enrolled, setEnrolled] = useState<string[]>([]);
  const [filter, setFilter] = useState<'All' | 'My Learning'>('All');
  const [isDownloading, setIsDownloading] = useState(false);
  const [user, setUser] = useState<string>('Trade Professional');

  // Learning & Quiz State
  const [activeLesson, setActiveLesson] = useState<{ course: Course, moduleIndex: number } | null>(null);
  const [lessonContent, setLessonContent] = useState<string>('');
  const [isLessonLoading, setIsLessonLoading] = useState(false);
  const [showQuiz, setShowQuiz] = useState(false);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [currentQuizStep, setCurrentQuizStep] = useState(0);
  const [quizScore, setQuizScore] = useState(0);
  const [isQuizLoading, setIsQuizLoading] = useState(false);
  const [isGraduated, setIsGraduated] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('donlemson_enrolled');
    if (saved) setEnrolled(JSON.parse(saved));
    const savedUser = localStorage.getItem('trade_user');
    if (savedUser) setUser(savedUser);
  }, []);

  const handleEnroll = (id: string) => {
    if (!enrolled.includes(id)) {
      const newEnrolled = [...enrolled, id];
      setEnrolled(newEnrolled);
      localStorage.setItem('donlemson_enrolled', JSON.stringify(newEnrolled));
      alert("Success! You are now enrolled. Click 'Start Learning' to begin.");
    }
  };

  const startLesson = async (course: Course, index: number = 0) => {
    setActiveLesson({ course, moduleIndex: index });
    setIsLessonLoading(true);
    setLessonContent('');
    setShowQuiz(false);
    setIsGraduated(false);
    setCurrentQuizStep(0);
    setQuizScore(0);

    try {
      const prompt = `Act as a world-class trade professor at DONLEMSONTRADE Global College. 
      The course is "${course.title}". 
      Teach Module ${index + 1}: "${course.modules[index]}" from beginning to end. 
      Provide a comprehensive, professional lesson with clear headers and actionable trade insights.`;

      const result = await chatWithGemini(prompt);
      setLessonContent(result.text);
    } catch (err) {
      setLessonContent("Failed to load lesson. Please retry.");
    } finally {
      setIsLessonLoading(false);
    }
  };

  const generateQuiz = async () => {
    if (!activeLesson) return;
    setIsQuizLoading(true);
    setCurrentQuizStep(0);
    setQuizScore(0);

    try {
      const prompt = `Generate a 3-question multiple choice quiz for the international trade module: "${activeLesson.course.modules[activeLesson.moduleIndex]}" within the course "${activeLesson.course.title}". 
      Return the response strictly as a JSON array of 3 objects. 
      Each object must have: 
      "question" (string), 
      "options" (array of 4 strings), 
      "correctAnswer" (number 0-3).`;

      const response = await chatWithGemini(prompt);
      const text = response.text;
      const jsonStart = text.indexOf('[');
      const jsonEnd = text.lastIndexOf(']') + 1;

      if (jsonStart === -1 || jsonEnd === 0) throw new Error("Format error");

      const jsonStr = text.substring(jsonStart, jsonEnd);
      const questions = JSON.parse(jsonStr);

      if (Array.isArray(questions) && questions.length > 0) {
        setQuizQuestions(questions);
        setShowQuiz(true);
      }
    } catch (err) {
      alert("AI Tutor is preparing questions. Please try again.");
    } finally {
      setIsQuizLoading(false);
    }
  };

  const handleAnswer = (selectedIndex: number) => {
    const isCorrect = selectedIndex === quizQuestions[currentQuizStep].correctAnswer;
    const newScore = isCorrect ? quizScore + 1 : quizScore;

    if (isCorrect) setQuizScore(newScore);

    if (currentQuizStep < quizQuestions.length - 1) {
      setCurrentQuizStep(currentQuizStep + 1);
    } else {
      if (newScore >= 2) {
        if (activeLesson!.moduleIndex === activeLesson!.course.modules.length - 1) {
          setIsGraduated(true);
        } else {
          alert(`Module passed (${newScore}/3)! Proceeding to next topic.`);
          startLesson(activeLesson!.course, activeLesson!.moduleIndex + 1);
        }
      } else {
        alert(`Score: ${newScore}/3. You need 2/3 to pass. Review and try again.`);
        setShowQuiz(false);
      }
    }
  };

  const downloadCertificatePDF = async () => {
    if (!activeLesson) return;
    const { jsPDF } = (window as any).jspdf;
    const doc = new jsPDF({
      orientation: 'landscape',
      unit: 'mm',
      format: 'a4'
    });

    const certId = `DTR-${Math.random().toString(36).substring(2, 10).toUpperCase()}`;
    const date = new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });

    // Design Elements
    doc.setFillColor(30, 58, 138); // Blue 900
    doc.rect(0, 0, 297, 210, 'F');

    // Border
    doc.setDrawColor(16, 185, 129); // Emerald 500
    doc.setLineWidth(2);
    doc.rect(10, 10, 277, 190);

    // Inner Border
    doc.setDrawColor(255, 255, 255);
    doc.setLineWidth(0.5);
    doc.rect(12, 12, 273, 186);

    // Header
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(24);
    doc.setFont("helvetica", "bold");
    doc.text("DONLEMSONTRADE GLOBAL COLLEGE", 148.5, 45, { align: "center" });

    doc.setTextColor(16, 185, 129);
    doc.setFontSize(14);
    doc.text("OFFICIAL CERTIFICATE OF MASTERY", 148.5, 55, { align: "center" });

    // Recipient
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(16);
    doc.setFont("helvetica", "normal");
    doc.text("This is to certify that", 148.5, 80, { align: "center" });

    doc.setFontSize(36);
    doc.setFont("helvetica", "bold");
    doc.text(user.toUpperCase(), 148.5, 100, { align: "center" });

    // Course
    doc.setFontSize(16);
    doc.setFont("helvetica", "normal");
    doc.text("has successfully completed the professional trade curriculum for:", 148.5, 120, { align: "center" });

    doc.setTextColor(16, 185, 129);
    doc.setFontSize(22);
    doc.setFont("helvetica", "bold");
    doc.text(`"${activeLesson.course.title}"`, 148.5, 135, { align: "center" });

    // Verification
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(10);
    doc.setFont("helvetica", "normal");
    doc.text(`Certificate ID: ${certId}`, 40, 175);
    doc.text(`Date of Issue: ${date}`, 40, 182);

    // Signature Area
    doc.setDrawColor(255, 255, 255);
    doc.line(200, 175, 260, 175);
    doc.text("Dr. Leo Donlems", 230, 182, { align: "center" });
    doc.setFontSize(8);
    doc.text("Dean of Global Logistics", 230, 187, { align: "center" });

    // Save
    doc.save(`DONLEMSONTRADE_CERT_${user.replace(/\s+/g, '_')}.pdf`);
  };

  const displayedCourses = filter === 'All' 
    ? TRADE_COURSES 
    : TRADE_COURSES.filter(c => enrolled.includes(c.id));

  return (
    <section className="bg-white border-y border-gray-200 py-16">
      <div className="max-w-7xl mx-auto px-4">
        {/* Header UI */}
        <div className="flex flex-col md:flex-row items-end justify-between mb-12 gap-6">
          <div className="max-w-2xl">
            <div className="flex items-center space-x-2 text-emerald-600 font-bold text-xs uppercase tracking-widest mb-2">
              <i className="fas fa-graduation-cap"></i>
              <span>Global Trade College</span>
            </div>
            <h2 className="text-3xl font-extrabold text-blue-900 mb-4 tracking-tight">Empowering Professionals Through Collaborative Learning</h2>
            <p className="text-gray-600 leading-relaxed font-medium">Earn professional credits and master Nigeria's international trade corridors with our AI-powered curriculum.</p>
          </div>
          <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200">
            <button onClick={() => setFilter('All')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${filter === 'All' ? 'bg-white text-blue-900 shadow-sm' : 'text-gray-500'}`}>All Courses</button>
            <button onClick={() => setFilter('My Learning')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all relative ${filter === 'My Learning' ? 'bg-white text-blue-900 shadow-sm' : 'text-gray-500'}`}>
              My Learning {enrolled.length > 0 && <span className="absolute -top-1 -right-1 w-4 h-4 bg-emerald-500 text-white text-[8px] flex items-center justify-center rounded-full border border-white">{enrolled.length}</span>}
            </button>
          </div>
        </div>

        {/* Course Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {displayedCourses.map(course => (
            <div key={course.id} className="bg-white border border-gray-200 rounded-2xl overflow-hidden shadow-sm flex flex-col hover:shadow-xl transition-all group">
              <div className="relative h-48 overflow-hidden">
                <img src={course.thumbnail} alt={course.title} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                <div className="absolute top-4 left-4 bg-white/90 backdrop-blur px-3 py-1 rounded-full text-[10px] font-bold text-blue-900 uppercase">{course.category}</div>
              </div>
              <div className="p-6 flex-1 flex flex-col">
                <h3 className="font-bold text-blue-900 text-lg mb-2 group-hover:text-emerald-600 transition-colors">{course.title}</h3>
                <p className="text-[11px] text-gray-400 font-bold uppercase mb-4 flex items-center">
                  <i className="fas fa-user-tie mr-2 text-emerald-500"></i> {course.instructor}
                </p>
                <div className="mt-auto pt-4 border-t border-gray-100 flex items-center justify-between">
                  <button onClick={() => setSelectedCourse(course)} className="text-[11px] font-bold text-blue-900 hover:text-emerald-600 uppercase tracking-widest transition">Curriculum</button>
                  {enrolled.includes(course.id) ? (
                    <button onClick={() => startLesson(course, 0)} className="bg-emerald-600 text-white px-5 py-2.5 rounded-xl text-xs font-bold hover:bg-emerald-700 transition-all shadow-md shadow-emerald-500/10">Start Learning</button>
                  ) : (
                    <button onClick={() => handleEnroll(course.id)} className="bg-blue-900 text-white px-5 py-2.5 rounded-xl text-xs font-bold hover:bg-blue-800 transition-all shadow-md shadow-blue-900/10">Enroll Now</button>
                  )}
                </div>
