        company: company || 'Self-Employed',
        role: role
      };
      onLogin(profile);
      setIsLoading(null);
      onClose();
    }, 1500);
  };

  const handleSocialLogin = (provider: string) => {
    setIsLoading(provider);
    setTimeout(() => {
      onLogin({ name: `User (${provider})`, company: 'Unknown', role: 'Professional' });
      setIsLoading(null);
      onClose();
    }, 2000);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-blue-900/60 backdrop-blur-md animate-in fade-in duration-300">
      <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl overflow-hidden transform transition-all animate-in zoom-in-95 duration-200">

        {isLoading && isLoading !== 'form' && (
          <div className="absolute inset-0 z-10 bg-white/90 backdrop-blur-sm flex flex-col items-center justify-center p-8 text-center">
            <div className="w-12 h-12 border-4 border-blue-900 border-t-transparent rounded-full animate-spin mb-4"></div>
            <h3 className="text-lg font-bold text-blue-900 uppercase tracking-tighter">Connecting to {isLoading}...</h3>
          </div>
        )}

        <div className="bg-blue-900 p-8 text-center relative">
          <button onClick={onClose} className="absolute top-4 right-4 text-blue-300 hover:text-white transition">
            <i className="fas fa-times text-lg"></i>
          </button>
          <div className="w-16 h-16 bg-white/10 rounded-2xl flex items-center justify-center mx-auto mb-4 border border-white/20 shadow-inner">
            <i className="fas fa-id-card text-3xl text-emerald-400"></i>
          </div>
          <h2 className="text-2xl font-bold text-white tracking-tight">Trade Professional Login</h2>
        </div>

        <div className="p-8 max-h-[70vh] overflow-y-auto">
          <form onSubmit={handleFormSubmit} className="space-y-4">
            <div>
              <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1.5">Email / Trade ID</label>
              <input required type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="sarah@export.ng" className="w-full bg-gray-50 border border-gray-200 rounded-xl py-3 px-4 focus:ring-2 focus:ring-blue-900/10 focus:border-blue-900 outline-none text-sm" />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1.5">Company</label>
                <input required type="text" value={company} onChange={(e) => setCompany(e.target.value)} placeholder="Global Ltd" className="w-full bg-gray-50 border border-gray-200 rounded-xl py-3 px-4 focus:ring-2 focus:ring-blue-900/10 focus:border-blue-900 outline-none text-sm" />
              </div>
              <div>
                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1.5">Primary Role</label>
                <select value={role} onChange={(e) => setRole(e.target.value)} className="w-full bg-gray-50 border border-gray-200 rounded-xl py-3 px-4 focus:ring-2 focus:ring-blue-900/10 focus:border-blue-900 outline-none text-sm">
                  <option>Importer</option>
                  <option>Exporter</option>
                  <option>Freight Forwarder</option>
                  <option>Clearing Agent</option>
                </select>
              </div>
            </div>

            <button disabled={isLoading !== null} type="submit" className="w-full bg-blue-900 text-white font-bold py-4 rounded-xl hover:bg-blue-800 transition-all flex items-center justify-center space-x-2">
              {isLoading === 'form' ? <i className="fas fa-circle-notch fa-spin"></i> : <span className="uppercase tracking-widest text-xs">Secure Login</span>}
            </button>
          </form>

          <div className="relative py-6">
            <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-gray-100"></div></div>
            <div className="relative flex justify-center text-[10px]"><span className="bg-white px-4 text-gray-400 font-bold uppercase tracking-widest">Social Connect</span></div>
          </div>

          <div className="grid grid-cols-3 gap-2">
            <button onClick={() => handleSocialLogin('Google')} className="border border-gray-200 rounded-xl py-2 hover:bg-gray-50"><i className="fab fa-google text-[#DB4437]"></i></button>
            <button onClick={() => handleSocialLogin('LinkedIn')} className="border border-gray-200 rounded-xl py-2 hover:bg-gray-50"><i className="fab fa-linkedin text-[#0077B5]"></i></button>
            <button onClick={() => handleSocialLogin('Microsoft')} className="border border-gray-200 rounded-xl py-2 hover:bg-gray-50"><i className="fab fa-microsoft text-[#00A4EF]"></i></button>
          </div>
        </div>
      </div>
    </div>
  );
};

