import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import ChatInterface from './components/ChatInterface';
import LoginModal from './components/LoginModal';
import GlobalCollege from './components/GlobalCollege';

interface UserProfile {
  name: string;
  company: string;
  role: string;
  coursesDone: string[]; // Store IDs of completed courses
}

const App: React.FC = () => {
  const [externalPrompt, setExternalPrompt] = useState<string | null>(null);
  const [isLoginModalOpen, setIsLoginModalOpen] = useState(false);
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem('donlemson_profile');
    if (saved) setUserProfile(JSON.parse(saved));
  }, []);

  const handleLogin = (profile: { name: string; company: string; role: string }) => {
    const newProfile: UserProfile = {
      ...profile,
      coursesDone: userProfile?.coursesDone || []
    };
    setUserProfile(newProfile);
    localStorage.setItem('donlemson_profile', JSON.stringify(newProfile));
  };

  const handleLogout = () => {
    setUserProfile(null);
    localStorage.removeItem('donlemson_profile');
    localStorage.removeItem('donlemson_enrolled');
  };

  const handleCourseComplete = (courseId: string) => {
    if (userProfile && !userProfile.coursesDone.includes(courseId)) {
      const updated = { ...userProfile, coursesDone: [...userProfile.coursesDone, courseId] };
      setUserProfile(updated);
      localStorage.setItem('donlemson_profile', JSON.stringify(updated));
    }
  };

  const handleQuickAction = (topic: string) => {
    let prompt = "";
    switch(topic) {
      case 'DONLEMSONTRADE Intelligence': prompt = "Tell me about the DONLEMSONTRADE intelligence platform and how it helps with Nigerian trade data and standards."; break;
      case 'Trade as a Service': prompt = "How does DONLEMSONTRADE 'Trade as a Service' model work for outsourcing export departments?"; break;
      case 'E-Learning': 
        document.getElementById('college-section')?.scrollIntoView({ behavior: 'smooth' });
        return;
      case 'Import': prompt = "Explain the Nigerian import process via DONLEMSONTRADE and best practices."; break;
      case 'Export': prompt = "What are the requirements for exporting goods from Nigeria internationally using DONLEMSONTRADE?"; break;
      case 'Regulations': prompt = "How do Nigerian trade regulations and agreements like AfCFTA affect my business?"; break;
      default: return;
    }
    setExternalPrompt(prompt);
    setTimeout(() => setExternalPrompt(null), 100);
  };

  return (
    <div className="min-h-screen flex flex-col bg-gray-50 font-sans">
      <Navbar 
        onAction={handleQuickAction} 
        onLoginClick={() => setIsLoginModalOpen(true)}
        user={userProfile?.name || null}
        onLogout={handleLogout}
      />

      <LoginModal 
        isOpen={isLoginModalOpen} 
        onClose={() => setIsLoginModalOpen(false)} 
        onLogin={handleLogin}
      />

      <header className="bg-white border-b border-gray-200 py-16 relative overflow-hidden">
        <div className="max-w-7xl mx-auto px-4 text-center relative z-10">
          {userProfile && (
            <div className="mb-6 inline-flex items-center space-x-2 bg-emerald-50 border border-emerald-100 px-4 py-2 rounded-full animate-in slide-in-from-top">
              <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
              <span className="text-xs font-bold text-emerald-700 uppercase tracking-widest">
                Professional Profile Active: {userProfile.name} @ {userProfile.company}
              </span>
            </div>
          )}
          <h1 className="text-4xl md:text-6xl font-black text-blue-900 mb-4 tracking-tighter">
            DONLEMSON<span className="text-emerald-600">TRADE</span>
          </h1>
          <p className="text-lg text-gray-500 max-w-2xl mx-auto font-medium">
            Nigeria's Digital Gateway to International Trade Excellence.
          </p>
        </div>
      </header>

      <main className="flex-1 space-y-0">
        <div id="college-section">
          <GlobalCollege 
            onCourseComplete={handleCourseComplete} 
            completedIds={userProfile?.coursesDone || []} 
          />
        </div>

        <section className="bg-slate-100 py-20 px-4">
          <div className="max-w-4xl mx-auto">
            <div className="text-center mb-10">
              <h2 className="text-3xl font-black text-blue-900 tracking-tight">Trade Intelligence Assistant</h2>
              {userProfile && <p className="text-gray-500 text-sm mt-2">Personalized support for {userProfile.role}s.</p>}
            </div>
            <ChatInterface externalPrompt={externalPrompt} />
          </div>
        </section>
      </main>

      <footer className="bg-white border-t border-gray-200 py-12">
        <div className="max-w-7xl mx-auto px-4 text-center">
          <div className="flex items-center justify-center space-x-2 mb-6">
            <div className="w-6 h-6 bg-blue-900 rounded flex items-center justify-center text-white text-[10px]"><i className="fas fa-globe"></i></div>
            <span className="font-bold text-blue-900 uppercase tracking-widest text-sm">DONLEMSONTRADE</span>
          </div>
          <p className="text-[10px] text-gray-400 font-bold tracking-widest uppercase">
            &copy; 2025 DONLEMSON TRADE CONSULTING. LAGOS, NIGERIA.
          </p>
        </div>
      </footer>
    </div>
  );
};

