import React, { useState, useEffect } from 'react';
import { TRADE_COURSES } from '../constants';
import { Course } from '../types';
import { chatWithGemini } from '../services/geminiService';

interface GlobalCollegeProps {
  onCourseComplete?: (courseId: string) => void;
  completedIds: string[];
}

interface QuizQuestion {
  question: string;
  options: string[];
  correctAnswer: number;
}

const GlobalCollege: React.FC<GlobalCollegeProps> = ({ onCourseComplete, completedIds }) => {
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [enrolled, setEnrolled] = useState<string[]>([]);
  const [filter, setFilter] = useState<'All' | 'My Learning'>('All');
  const [userProfile, setUserProfile] = useState<any>(null);

  const [activeLesson, setActiveLesson] = useState<{ course: Course, moduleIndex: number } | null>(null);
  const [lessonContent, setLessonContent] = useState<string>('');
  const [isLessonLoading, setIsLessonLoading] = useState(false);
  const [showQuiz, setShowQuiz] = useState(false);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [currentQuizStep, setCurrentQuizStep] = useState(0);
  const [quizScore, setQuizScore] = useState(0);
  const [isQuizLoading, setIsQuizLoading] = useState(false);
  const [isGraduated, setIsGraduated] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('donlemson_enrolled');
    if (saved) setEnrolled(JSON.parse(saved));
    const profile = localStorage.getItem('donlemson_profile');
    if (profile) setUserProfile(JSON.parse(profile));
  }, []);

  const handleEnroll = (id: string) => {
    if (!enrolled.includes(id)) {
      const newEnrolled = [...enrolled, id];
      setEnrolled(newEnrolled);
      localStorage.setItem('donlemson_enrolled', JSON.stringify(newEnrolled));
    }
  };

  const startLesson = async (course: Course, index: number = 0) => {
    setActiveLesson({ course, moduleIndex: index });
    setIsLessonLoading(true);
    setLessonContent('');
    setShowQuiz(false);
    setIsGraduated(false);
    setCurrentQuizStep(0);
    setQuizScore(0);

    try {
      const prompt = `Act as a world-class trade professor at DONLEMSONTRADE Global College. 
      The student is ${userProfile?.name || 'a professional'} from ${userProfile?.company || 'their company'}.
      The course is "${course.title}". 
      Teach Module ${index + 1}: "${course.modules[index]}".`;

      const result = await chatWithGemini(prompt);
      setLessonContent(result.text);
    } catch (err) {
      setLessonContent("Failed to load lesson. Please retry.");
    } finally {
      setIsLessonLoading(false);
    }
  };

  const generateQuiz = async () => {
    if (!activeLesson) return;
    setIsQuizLoading(true);
    try {
      const prompt = `Generate a 3-question MCQ quiz for: "${activeLesson.course.modules[activeLesson.moduleIndex]}". 
      Return as JSON array of objects: {question: string, options: string[], correctAnswer: number}.`;
      const response = await chatWithGemini(prompt);
      const jsonStart = response.text.indexOf('[');
      const jsonEnd = response.text.lastIndexOf(']') + 1;
      setQuizQuestions(JSON.parse(response.text.substring(jsonStart, jsonEnd)));
      setShowQuiz(true);
    } catch (err) {
      alert("Error generating assessment.");
    } finally {
      setIsQuizLoading(false);
    }
  };

  const handleAnswer = (selectedIndex: number) => {
    const isCorrect = selectedIndex === quizQuestions[currentQuizStep].correctAnswer;
    const newScore = isCorrect ? quizScore + 1 : quizScore;
    if (isCorrect) setQuizScore(newScore);

    if (currentQuizStep < quizQuestions.length - 1) {
      setCurrentQuizStep(currentQuizStep + 1);
    } else {
      if (newScore >= 2) {
        if (activeLesson!.moduleIndex === activeLesson!.course.modules.length - 1) {
          setIsGraduated(true);
          onCourseComplete?.(activeLesson!.course.id);
        } else {
          alert("Module passed! Moving to next topic.");
          startLesson(activeLesson!.course, activeLesson!.moduleIndex + 1);
        }
      } else {
        alert("Review and retry.");
        setShowQuiz(false);
      }
    }
  };

  const downloadCertificatePDF = () => {
    const { jsPDF } = (window as any).jspdf;
    const doc = new jsPDF({ orientation: 'landscape' });
    doc.setFillColor(30, 58, 138); doc.rect(0, 0, 297, 210, 'F');
    doc.setTextColor(255, 255, 255); doc.setFontSize(26);
    doc.text("DONLEMSONTRADE GLOBAL COLLEGE", 148, 50, { align: "center" });
    doc.setFontSize(18); doc.text("CERTIFICATE OF COMPLETION", 148, 65, { align: "center" });
    doc.setFontSize(40); doc.text(userProfile?.name?.toUpperCase() || "TRADE PROFESSIONAL", 148, 100, { align: "center" });
    doc.setFontSize(16); doc.text(`Completed: ${activeLesson?.course.title}`, 148, 130, { align: "center" });
    doc.text(`Company: ${userProfile?.company || 'International Trade'}`, 148, 145, { align: "center" });
    doc.save(`Certificate_${userProfile?.name || 'User'}.pdf`);
  };

  const displayedCourses = filter === 'All' ? TRADE_COURSES : TRADE_COURSES.filter(c => enrolled.includes(c.id));

  return (
    <section className="bg-white border-y border-gray-200 py-16">
      <div className="max-w-7xl mx-auto px-4">
        <div className="flex flex-col md:flex-row items-end justify-between mb-12 gap-6">
          <div className="max-w-xl">
            <h2 className="text-3xl font-black text-blue-900 tracking-tight">Global Trade College</h2>
            {userProfile && (
              <p className="text-emerald-600 text-xs font-bold uppercase mt-2">
                Student: {userProfile.name} | Completed: {completedIds.length} Courses
              </p>
            )}
          </div>
          <div className="flex bg-gray-100 p-1 rounded-xl">
            <button onClick={() => setFilter('All')} className={`px-6 py-2 rounded-lg text-xs font-black uppercase tracking-widest ${filter === 'All' ? 'bg-white text-blue-900 shadow-sm' : 'text-gray-400'}`}>All</button>
            <button onClick={() => setFilter('My Learning')} className={`px-6 py-2 rounded-lg text-xs font-black uppercase tracking-widest ${filter === 'My Learning' ? 'bg-white text-blue-900 shadow-sm' : 'text-gray-400'}`}>My Deck</button>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {displayedCourses.map(course => (
            <div key={course.id} className={`bg-white border rounded-2xl overflow-hidden shadow-sm flex flex-col hover:shadow-lg transition-all ${completedIds.includes(course.id) ? 'border-emerald-200 bg-emerald-50/20' : 'border-gray-200'}`}>
              <div className="relative h-44 overflow-hidden">
                <img src={course.thumbnail} alt={course.title} className="w-full h-full object-cover" />
                {completedIds.includes(course.id) && (
                  <div className="absolute top-2 right-2 bg-emerald-500 text-white px-2 py-1 rounded-lg text-[10px] font-black uppercase flex items-center">
                    <i className="fas fa-check-circle mr-1"></i> Completed
                  </div>
                )}
              </div>
              <div className="p-6 flex-1 flex flex-col">
                <h3 className="font-bold text-blue-900 text-lg mb-4">{course.title}</h3>
                <div className="mt-auto pt-4 border-t flex items-center justify-between">
                  <button onClick={() => setSelectedCourse(course)} className="text-[10px] font-black text-blue-900 uppercase">Syllabus</button>
                  {enrolled.includes(course.id) ? (
                    <button onClick={() => startLesson(course, 0)} className="bg-emerald-600 text-white px-4 py-2 rounded-xl text-xs font-black uppercase">{completedIds.includes(course.id) ? 'Review' : 'Resume'}</button>
                  ) : (
                    <button onClick={() => handleEnroll(course.id)} className="bg-blue-900 text-white px-4 py-2 rounded-xl text-xs font-black uppercase">Enroll</button>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {activeLesson && (
        <div className="fixed inset-0 z-[200] bg-white flex flex-col">
          <div className="bg-blue-900 px-6 py-4 text-white flex items-center justify-between">
            <button onClick={() => setActiveLesson(null)} className="w-8 h-8 rounded-full hover:bg-white/10 flex items-center justify-center"><i className="fas fa-times"></i></button>
            <span className="text-xs font-black uppercase tracking-widest">{activeLesson.course.title}</span>
            <div className="w-8"></div>
          </div>
          <div className="flex-1 overflow-y-auto p-6 md:p-12">
            <div className="max-w-2xl mx-auto">
              {isGraduated ? (
                <div className="text-center py-16 bg-emerald-50 rounded-3xl border border-emerald-100 px-6">
                  <i className="fas fa-award text-5xl text-emerald-500 mb-6"></i>
                  <h2 className="text-3xl font-black text-blue-900 mb-4 uppercase tracking-tighter">Certified Professional</h2>
                  <p className="text-gray-600 mb-8 font-medium">Excellent work, {userProfile?.name || 'Trader'}. You have mastered this curriculum.</p>
                  <button onClick={downloadCertificatePDF} className="bg-blue-900 text-white px-8 py-4 rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl">Download PDF <i className="fas fa-file-pdf ml-2"></i></button>
                </div>
              ) : showQuiz ? (
                <div className="animate-in fade-in slide-in-from-right">
                  <h2 className="text-2xl font-black text-blue-900 mb-8">{quizQuestions[currentQuizStep].question}</h2>
                  <div className="space-y-3">
                    {quizQuestions[currentQuizStep].options.map((opt, i) => (
                      <button key={i} onClick={() => handleAnswer(i)} className="w-full text-left p-5 rounded-2xl border-2 border-slate-100 hover:border-emerald-500 hover:bg-emerald-50 transition-all font-bold text-slate-700">{opt}</button>
                    ))}
                  </div>
                </div>
              ) : (
                <div>
                  <h1 className="text-3xl font-black text-blue-900 mb-8 tracking-tighter uppercase">{activeLesson.course.modules[activeLesson.moduleIndex]}</h1>
                  {isLessonLoading ? <div className="animate-pulse space-y-4"><div className="h-4 bg-slate-100 rounded-full w-3/4"></div><div className="h-4 bg-slate-100 rounded-full"></div><div className="h-4 bg-slate-100 rounded-full w-5/6"></div></div> : (
                    <div className="prose prose-slate max-w-none text-slate-700 leading-relaxed font-medium">
                      <div className="whitespace-pre-wrap mb-12">{lessonContent}</div>
                      <div className="p-8 bg-blue-50 rounded-[32px] border border-blue-100 flex items-center justify-between">
                        <span className="font-black text-blue-900 text-sm tracking-tight">Ready for the module assessment?</span>
                        <button onClick={generateQuiz} className="bg-blue-900 text-white px-6 py-3 rounded-xl font-black text-xs uppercase tracking-widest shadow-lg">Start Quiz</button>
                      </div>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </section>
  );
};

