  currentUserName?: string;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({ externalPrompt, onOpenLogin, currentUserName }) => {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: '1',
      role: 'assistant',
      content: "Hello! I'm your DONLEMSONTRADE global consultant. How can I assist with your international trade queries today?",
      timestamp: Date.now(),
    }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [imageMime, setImageMime] = useState<string>('');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading]);

  useEffect(() => {
    if (externalPrompt) {
      handleSend(externalPrompt);
    }
  }, [externalPrompt]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
        setImageMime(file.type);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async (overrideInput?: string) => {
    const messageText = overrideInput || input;
    if (!messageText.trim() && !selectedImage) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: messageText,
      image: selectedImage || undefined,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMessage]);
    if (!overrideInput) setInput('');
    setIsLoading(true);

    try {
      if (selectedImage) {
        const result = await editTradeImage(messageText || "Analyze this trade document or product.", selectedImage, imageMime);
        const assistantMessage: Message = {
          id: (Date.now() + 1).toString(),
          role: 'assistant',
          content: result.feedbackText || "I've processed the image for you.",
          image: result.imageUrl || undefined,
          timestamp: Date.now(),
        };
        setMessages(prev => [...prev, assistantMessage]);
      } else {
        const result = await chatWithGemini(messageText);

        const lowerText = messageText.toLowerCase();
        const isAuthRequest = lowerText.includes('sign in') || lowerText.includes('login') || lowerText.includes('register') || lowerText.includes('log in');

        const assistantMessage: Message = {
          id: (Date.now() + 1).toString(),
          role: 'assistant',
          content: isAuthRequest ? `${result.text}\n\nI have initiated the Portal Login for you. Please complete the professional verification.` : result.text,
          sources: result.sources,
          timestamp: Date.now(),
        };
        setMessages(prev => [...prev, assistantMessage]);

        if (isAuthRequest && onOpenLogin) {
          // Attempt to extract name if the user said "I am [Name], sign me in"
          let nameToPrefill = currentUserName || "";
          const nameMatch = messageText.match(/i am\s+([a-zA-Z\s]+)/i);
          if (nameMatch && nameMatch[1]) nameToPrefill = nameMatch[1].trim();

          onOpenLogin(nameToPrefill);
        }
      }
    } catch (error) {
      console.error(error);
      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: "I'm sorry, I hit a snag. Could you try asking again?",
        timestamp: Date.now(),
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
      setSelectedImage(null);
    }
  };

  return (
    <div className="flex flex-col h-[600px] bg-white rounded-xl shadow-lg overflow-hidden border border-gray-200">
      <div className="bg-blue-900 px-6 py-4 flex items-center justify-between shadow-sm">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 rounded-full bg-blue-800 flex items-center justify-center text-white border border-blue-700">
            <i className="fas fa-robot text-lg"></i>
          </div>
          <div>
            <h3 className="font-bold text-white text-sm">Trade AI Support</h3>
            <p className="text-[10px] text-blue-300 font-bold uppercase tracking-widest">Global Intelligence</p>
          </div>
        </div>
        <LiveVoiceChat onOpenLogin={onOpenLogin} />
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-gray-50/30">
        {messages.map((m) => {
          const isAuthResponse = m.role === 'assistant' && (m.content.toLowerCase().includes('portal login') || m.content.toLowerCase().includes('complete the professional verification'));

          return (
            <div key={m.id} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] ${m.role === 'user' ? 'ml-8' : 'mr-8'}`}>
                <div className={`px-4 py-3 rounded-xl shadow-sm ${
                  m.role === 'user' 
                    ? 'bg-blue-900 text-white rounded-tr-none' 
                    : 'bg-white text-gray-800 rounded-tl-none border border-gray-200'
                }`}>
                  {m.image && (
                    <div className="mb-3 rounded-lg overflow-hidden border border-gray-100">
                      <img src={m.image} alt="Trade Content" className="max-h-60 w-full object-contain" />
                    </div>
                  )}
                  <div className="text-[14px] leading-relaxed whitespace-pre-wrap">
                    {m.content}
                  </div>

                  {isAuthResponse && onOpenLogin && (
                    <button 
                      onClick={() => onOpenLogin()}
                      className="mt-4 w-full bg-blue-900 text-white py-3 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-emerald-600 transition-colors shadow-lg flex items-center justify-center space-x-2"
                    >
                      <i className="fas fa-lock"></i>
                      <span>Open Portal Login</span>
                    </button>
                  )}

                  {m.sources && m.sources.length > 0 && (
                    <div className="mt-3 pt-3 border-t border-gray-100">
                      <p className="text-[9px] font-bold text-blue-600 uppercase tracking-widest mb-2">Sources</p>
                      <div className="flex flex-wrap gap-2">
                        {m.sources.map((src, idx) => (
                          <a key={idx} href={src.uri} target="_blank" rel="noreferrer" className="bg-blue-50 text-blue-800 text-[10px] px-2 py-1 rounded border border-blue-100 hover:bg-blue-100 transition">
                            {src.title}
                          </a>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
                <p className={`text-[9px] mt-1 text-gray-400 font-medium ${m.role === 'user' ? 'text-right' : 'text-left'}`}>
                  {new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </p>
              </div>
            </div>
          );
        })}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-white px-4 py-3 rounded-xl border border-gray-200">
              <div className="flex space-x-1">
                <div className="w-1.5 h-1.5 bg-blue-300 rounded-full animate-bounce"></div>
                <div className="w-1.5 h-1.5 bg-blue-300 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                <div className="w-1.5 h-1.5 bg-blue-300 rounded-full animate-bounce [animation-delay:0.4s]"></div>
              </div>
            </div>
          </div>
        )}
        <div ref={chatEndRef} />
      </div>

      <div className="p-4 bg-white border-t border-gray-200">
        <div className="flex items-center space-x-2">
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="w-10 h-10 flex items-center justify-center rounded-lg bg-gray-50 border border-gray-200 text-gray-500 hover:text-blue-900 transition"
          >
            <i className="fas fa-camera"></i>
          </button>
          <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*" />
          <div className="flex-1 relative">
            <input 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Type your message..."
              className="w-full bg-gray-50 border border-gray-200 rounded-lg py-2.5 pl-4 pr-12 focus:outline-none focus:ring-1 focus:ring-blue-900 focus:bg-white transition-all text-sm"
            />
            <button 
              onClick={() => handleSend()}
              disabled={isLoading || (!input.trim() && !selectedImage)}
              className="absolute right-1.5 top-1.5 w-7 h-7 bg-blue-900 text-white rounded flex items-center justify-center disabled:opacity-50"
            >
              <i className="fas fa-paper-plane text-[10px]"></i>
            </button>
          </div>
        </div>
        {selectedImage && (
          <div className="mt-3 relative inline-block">
            <img src={selectedImage} alt="Preview" className="h-16 w-16 object-cover rounded border border-gray-200" />
            <button onClick={() => setSelectedImage(null)} className="absolute -top-2 -right-2 bg-red-500 text-white w-4 h-4 rounded-full flex items-center justify-center text-[8px]">
              <i className="fas fa-times"></i>
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default ChatInterface;

