import React, { useState, useRef, useCallback } from 'react';
import { GoogleGenAI, Modality } from '@google/genai';
import { SYSTEM_PROMPT } from '../constants';

interface LiveVoiceChatProps {
  onOpenLogin?: (name?: string) => void;
}

const LiveVoiceChat: React.FC<LiveVoiceChatProps> = ({ onOpenLogin }) => {
  const [isActive, setIsActive] = useState(false);
  const [isConnecting, setIsConnecting] = useState(false);
  const sessionRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length;
    const buffer = ctx.createBuffer(1, frameCount, 24000);
    const channelData = buffer.getChannelData(0);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i] / 32768.0;
    }
    return buffer;
  };

  const encodePCM = (data: Float32Array): string => {
    const int16 = new Int16Array(data.length);
    for (let i = 0; i < data.length; i++) {
      int16[i] = Math.max(-1, Math.min(1, data[i])) * 32767;
    }
    const bytes = new Uint8Array(int16.buffer);
    let binary = '';
    for (let i = 0; i < bytes.byteLength; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) {
      sessionRef.current = null;
    }
    if (audioContextRef.current) {
      audioContextRef.current.close();
      audioContextRef.current = null;
    }
    sourcesRef.current.forEach(s => s.stop());
    sourcesRef.current.clear();
    setIsActive(false);
    setIsConnecting(false);
  }, []);

  const startSession = async () => {
    try {
      setIsConnecting(true);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const inputContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const profileStr = localStorage.getItem('donlemson_profile');
      const profile = profileStr ? JSON.parse(profileStr) : null;
      const userName = profile?.name || "Trade Professional";

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          },
          systemInstruction: SYSTEM_PROMPT + `\n\nLIVE VOICE MODE: You are talking to ${userName}.
          SIGN-IN ASSISTANCE: If the user asks to sign in, login, or register, tell them: "I am opening the secure portal for you now, [Name]". 
          Try to identify if they said their name during the conversation. 
          Speak directly and concisely. Do NOT ask for their name if it was already mentioned.`
        },
        callbacks: {
          onopen: () => {
            setIsConnecting(false);
            setIsActive(true);
            const source = inputContext.createMediaStreamSource(stream);
            const processor = inputContext.createScriptProcessor(4096, 1, 1);

            processor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const base64Pcm = encodePCM(inputData);
              sessionPromise.then(session => {
                session.sendRealtimeInput({
                  media: { data: base64Pcm, mimeType: 'audio/pcm;rate=16000' }
                });
              });
            };

            source.connect(processor);
            processor.connect(inputContext.destination);
          },
          onmessage: async (message) => {
            const transcriptText = message.serverContent?.outputTranscription?.text || "";
            const inputTranscript = message.serverContent?.inputTranscription?.text || "";

            // Check if login was requested
            if (transcriptText.toLowerCase().includes("opening the secure portal") || 
                transcriptText.toLowerCase().includes("portal login")) {

              // Extract name from user's input if they said "I am [Name]"
              let inferredName = "";
              const nameMatch = inputTranscript.match(/i am\s+([a-zA-Z\s]+)/i);
              if (nameMatch && nameMatch[1]) inferredName = nameMatch[1].trim();

              onOpenLogin?.(inferredName);
            }

            const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData && audioContextRef.current) {
              const ctx = audioContextRef.current;
              const binary = atob(audioData);
              const bytes = new Uint8Array(binary.length);
              for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);

              const buffer = await decodeAudioData(bytes, ctx);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);

              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
              source.onended = () => sourcesRef.current.delete(source);
            }

            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => s.stop());
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
            }
          },
          onclose: () => stopSession(),
          onerror: (e) => {
            console.error("Live Audio Error:", e);
            stopSession();
          }
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (err) {
      console.error("Failed to start live session:", err);
      setIsConnecting(false);
      stopSession();
    }
  };

  return (
    <div className="flex items-center space-x-2">
      {isActive ? (
        <button 
          onClick={stopSession}
          className="flex items-center space-x-2 bg-red-500 hover:bg-red-600 text-white px-4 py-2 rounded-full shadow-lg transition-all animate-pulse"
        >
          <i className="fas fa-stop-circle"></i>
          <span className="text-xs font-bold uppercase tracking-wider">End Live Consult</span>
        </button>
      ) : (
        <button 
          onClick={startSession}
          disabled={isConnecting}
          className={`flex items-center space-x-2 px-4 py-2 rounded-full shadow-lg transition-all ${
            isConnecting ? 'bg-slate-300 text-slate-500 cursor-not-allowed' : 'bg-emerald-600 hover:bg-emerald-700 text-white'
          }`}
        >
          {isConnecting ? (
            <i className="fas fa-spinner fa-spin"></i>
          ) : (
            <i className="fas fa-microphone"></i>
          )}
          <span className="text-xs font-bold uppercase tracking-wider">
            {isConnecting ? 'Connecting...' : 'Live Voice Consult'}
          </span>
        </button>
      )}

      {isActive && (
        <div className="flex space-x-1 items-center px-2">
          {[1, 2, 3, 4].map(i => (
            <div 
              key={i} 
              className="w-1 bg-emerald-500 rounded-full animate-bounce" 
              style={{ height: `${Math.random() * 16 + 4}px`, animationDelay: `${i * 0.1}s` }}
            ></div>
          ))}
        </div>
      )}
    </div>
  );
};

export default LiveVoiceChat;

import React, { useState, useRef, useEffect } from 'react';
import { Message } from '../types';
import { chatWithGemini, editTradeImage } from '../services/geminiService';
import LiveVoiceChat from './LiveVoiceChat';

interface ChatInterfaceProps {
  externalPrompt?: string | null;
  onOpenLogin?: (name?: string) => void;
  currentUserName?: string;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({ externalPrompt, onOpenLogin, currentUserName }) => {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: '1',
      role: 'assistant',
      content: "Hello! I'm your DONLEMSONTRADE global consultant. I'm here to guide you through the complexities of international trade. How can I assist you today?",
      timestamp: Date.now(),
    }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [imageMime, setImageMime] = useState<string>('');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading]);

  useEffect(() => {
    if (externalPrompt) {
      handleSend(externalPrompt);
    }
  }, [externalPrompt]);

  // Update initial greeting if name becomes available
  useEffect(() => {
    if (currentUserName && messages.length === 1 && messages[0].id === '1') {
      setMessages([{
        ...messages[0],
        content: `Hello ${currentUserName}! I'm your DONLEMSONTRADE global consultant. It's great to have you here. How can I assist with your international trade queries today?`
      }]);
    }
  }, [currentUserName]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
        setImageMime(file.type);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async (overrideInput?: string) => {
    const messageText = overrideInput || input;
    if (!messageText.trim() && !selectedImage) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: messageText,
      image: selectedImage || undefined,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMessage]);
    if (!overrideInput) setInput('');
    setIsLoading(true);

    try {
      if (selectedImage) {
        const result = await editTradeImage(messageText || "Analyze this trade document.", selectedImage, imageMime);
        const assistantMessage: Message = {
          id: (Date.now() + 1).toString(),
          role: 'assistant',
          content: result.feedbackText || "I've processed the document for you.",
          image: result.imageUrl || undefined,
          timestamp: Date.now(),
        };
        setMessages(prev => [...prev, assistantMessage]);
      } else {
        // Pass name context to the service
        const contextPrompt = currentUserName ? `(User Name: ${currentUserName}) ${messageText}` : messageText;
        const result = await chatWithGemini(contextPrompt);

        const lowerText = messageText.toLowerCase();
        const isAuthRequest = lowerText.includes('sign in') || lowerText.includes('login') || lowerText.includes('register') || lowerText.includes('log in');

        const assistantMessage: Message = {
          id: (Date.now() + 1).toString(),
          role: 'assistant',
          content: isAuthRequest 
            ? `Certainly ${currentUserName || 'my friend'}! I've initiated the Portal Login for you. Please complete the professional verification so we can get started with your secure dashboard.` 
            : result.text,
          sources: result.sources,
          timestamp: Date.now(),
        };
        setMessages(prev => [...prev, assistantMessage]);

        if (isAuthRequest && onOpenLogin) {
          let nameToPrefill = currentUserName || "";
          const nameMatch = messageText.match(/i am\s+([a-zA-Z\s]+)/i);
          if (nameMatch && nameMatch[1]) nameToPrefill = nameMatch[1].trim();
          onOpenLogin(nameToPrefill);
        }
      }
    } catch (error) {
      console.error(error);
      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: "I'm sorry, I hit a snag. Could you try asking again?",
        timestamp: Date.now(),
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
      setSelectedImage(null);
    }
  };

  return (
    <div className="flex flex-col h-[600px] bg-white rounded-xl shadow-lg overflow-hidden border border-gray-200">
      <div className="bg-blue-900 px-6 py-4 flex items-center justify-between shadow-sm">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 rounded-full bg-blue-800 flex items-center justify-center text-white border border-blue-700">
            <i className="fas fa-robot text-lg"></i>
          </div>
          <div>
            <h3 className="font-bold text-white text-sm">
              {currentUserName ? `Consulting ${currentUserName.split(' ')[0]}` : 'Trade AI Support'}
            </h3>
            <p className="text-[10px] text-blue-300 font-bold uppercase tracking-widest">Global Intelligence</p>
          </div>
        </div>
        <LiveVoiceChat onOpenLogin={onOpenLogin} />
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-gray-50/30">
        {messages.map((m) => {
          const isAuthResponse = m.role === 'assistant' && (m.content.toLowerCase().includes('portal login') || m.content.toLowerCase().includes('complete the professional verification'));

          return (
            <div key={m.id} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] ${m.role === 'user' ? 'ml-8' : 'mr-8'}`}>
                <div className={`px-4 py-3 rounded-xl shadow-sm ${
                  m.role === 'user' 
                    ? 'bg-blue-900 text-white rounded-tr-none' 
                    : 'bg-white text-gray-800 rounded-tl-none border border-gray-200'
                }`}>
                  {m.image && (
                    <div className="mb-3 rounded-lg overflow-hidden border border-gray-100">
                      <img src={m.image} alt="Trade Content" className="max-h-60 w-full object-contain" />
                    </div>
                  )}
                  <div className="text-[14px] leading-relaxed whitespace-pre-wrap">
                    {m.content}
                  </div>

                  {isAuthResponse && onOpenLogin && (
                    <button 
                      onClick={() => onOpenLogin(currentUserName)}
                      className="mt-4 w-full bg-blue-900 text-white py-3 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-emerald-600 transition-colors shadow-lg flex items-center justify-center space-x-2"
                    >
                      <i className="fas fa-lock"></i>
                      <span>Open Portal Login</span>
                    </button>
                  )}

                  {m.sources && m.sources.length > 0 && (
                    <div className="mt-3 pt-3 border-t border-gray-100">
                      <p className="text-[9px] font-bold text-blue-600 uppercase tracking-widest mb-2">Sources</p>
                      <div className="flex flex-wrap gap-2">
                        {m.sources.map((src, idx) => (
                          <a key={idx} href={src.uri} target="_blank" rel="noreferrer" className="bg-blue-50 text-blue-800 text-[10px] px-2 py-1 rounded border border-blue-100 hover:bg-blue-100 transition">
                            {src.title}
                          </a>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
                <p className={`text-[9px] mt-1 text-gray-400 font-medium ${m.role === 'user' ? 'text-right' : 'text-left'}`}>
                  {new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </p>
              </div>
            </div>
          );
        })}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-white px-4 py-3 rounded-xl border border-gray-200">
              <div className="flex space-x-1">
                <div className="w-1.5 h-1.5 bg-blue-300 rounded-full animate-bounce"></div>
                <div className="w-1.5 h-1.5 bg-blue-300 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                <div className="w-1.5 h-1.5 bg-blue-300 rounded-full animate-bounce [animation-delay:0.4s]"></div>
              </div>
            </div>
          </div>
        )}
        <div ref={chatEndRef} />
      </div>

      <div className="p-4 bg-white border-t border-gray-200">
        <div className="flex items-center space-x-2">
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="w-10 h-10 flex items-center justify-center rounded-lg bg-gray-50 border border-gray-200 text-gray-500 hover:text-blue-900 transition"
          >
            <i className="fas fa-camera"></i>
          </button>
          <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*" />
          <div className="flex-1 relative">
            <input 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Type your message..."
              className="w-full bg-gray-50 border border-gray-200 rounded-lg py-2.5 pl-4 pr-12 focus:outline-none focus:ring-1 focus:ring-blue-900 focus:bg-white transition-all text-sm"
            />
            <button 
              onClick={() => handleSend()}
              disabled={isLoading || (!input.trim() && !selectedImage)}
              className="absolute right-1.5 top-1.5 w-7 h-7 bg-blue-900 text-white rounded flex items-center justify-center disabled:opacity-50"
            >
              <i className="fas fa-paper-plane text-[10px]"></i>
            </button>
          </div>
        </div>
        {selectedImage && (
          <div className="mt-3 relative inline-block">
            <img src={selectedImage} alt="Preview" className="h-16 w-16 object-cover rounded border border-gray-200" />
            <button onClick={() => setSelectedImage(null)} className="absolute -top-2 -right-2 bg-red-500 text-white w-4 h-4 rounded-full flex items-center justify-center text-[8px]">
              <i className="fas fa-times"></i>
