import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";
import { SYSTEM_PROMPT } from "../constants";

const getAIClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
};

export const chatWithGemini = async (prompt: string, history: any[] = []) => {
  const ai = getAIClient();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_PROMPT,
      tools: [{ googleSearch: {} }],
      temperature: 0.1,
    },
  });

  return {
    text: response.text || "I'm sorry, I couldn't process that request.",
    sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || 'Source',
      uri: chunk.web?.uri || ''
    })).filter((s: any) => s.uri) || []
  };
};

export const getLatestTradeNews = async () => {
  const ai = getAIClient();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: "Find the latest 5 news items related to Nigeria International Trade, specifically CBN circulars, Nigeria Customs Service (NCS) directives, and AfCFTA updates from the last 30 days.",
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            summary: { type: Type.STRING },
            category: { type: Type.STRING },
            date: { type: Type.STRING },
            url: { type: Type.STRING }
          },
          required: ["title", "summary", "category", "date", "url"]
        }
      }
    }
  });

  try {
    return JSON.parse(response.text);
  } catch (e) {
    console.error("Failed to parse news", e);
    return [];
  }
};

export const editTradeImage = async (prompt: string, base64Image: string, mimeType: string) => {
  const ai = getAIClient();
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Image.split(',')[1],
            mimeType: mimeType,
          },
        },
        {
          text: `You are an expert for Nigerian trade documents. Analyze this image and respond IMMEDIATELY with facts. User request: ${prompt}. If not trade-related, decline politely. DO NOT use filler phrases like 'In the context of trade'.`,
        },
      ],
    },
  });

  let imageUrl = '';
  let feedbackText = '';

  for (const part of response.candidates?.[0]?.content.parts || []) {
    if (part.inlineData) {
      imageUrl = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    } else if (part.text) {
      feedbackText = part.text;
    }
  }

  return { imageUrl, feedbackText };
};

import React, { useState, useEffect } from 'react';
