  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (isOpen) {
      fetchNews();
    }
  }, [isOpen]);

  const fetchNews = async () => {
    setLoading(true);
    const data = await getLatestTradeNews();
    setNews(data);
    setLoading(false);
