import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import ChatInterface from './components/ChatInterface';
import LoginModal from './components/LoginModal';
import GlobalCollege from './components/GlobalCollege';
import NewsFeed from './components/NewsFeed';
import ContactOverlay from './components/ContactOverlay';

interface UserProfile {
  name: string;
  company: string;
  role: string;
  coursesDone: string[]; 
}

const App: React.FC = () => {
  const [externalPrompt, setExternalPrompt] = useState<string | null>(null);
  const [isLoginModalOpen, setIsLoginModalOpen] = useState(false);
  const [isNewsOpen, setIsNewsOpen] = useState(false);
  const [isContactOpen, setIsContactOpen] = useState(false);
  const [prefillName, setPrefillName] = useState('');
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem('donlemson_profile');
    if (saved) setUserProfile(JSON.parse(saved));
  }, []);

  const handleLogin = (profile: { name: string; company: string; role: string }) => {
    const newProfile: UserProfile = {
      ...profile,
      coursesDone: userProfile?.coursesDone || []
    };
    setUserProfile(newProfile);
    localStorage.setItem('donlemson_profile', JSON.stringify(newProfile));
  };

  const handleLogout = () => {
    setUserProfile(null);
    localStorage.removeItem('donlemson_profile');
    localStorage.removeItem('donlemson_enrolled');
  };

  const handleOpenLogin = (name?: string) => {
    if (name) setPrefillName(name);
    setIsLoginModalOpen(true);
  };

  const handleCourseComplete = (courseId: string) => {
    if (userProfile && !userProfile.coursesDone.includes(courseId)) {
      const updated = { ...userProfile, coursesDone: [...userProfile.coursesDone, courseId] };
      setUserProfile(updated);
      localStorage.setItem('donlemson_profile', JSON.stringify(updated));
    }
  };

  const handleQuickAction = (topic: string) => {
    let prompt = "";
    switch(topic) {
      case 'DONLEMSONTRADE Intelligence': prompt = "Tell me about the DONLEMSONTRADE intelligence platform and how it helps with Nigerian trade data and standards."; break;
      case 'Trade as a Service': prompt = "How does DONLEMSONTRADE 'Trade as a Service' model work for outsourcing export departments?"; break;
      case 'E-Learning': 
        document.getElementById('college-section')?.scrollIntoView({ behavior: 'smooth' });
        return;
      case 'News':
        setIsNewsOpen(true);
        return;
      case 'Contact':
        setIsContactOpen(true);
        return;
      case 'Import': prompt = "Explain the Nigerian import process via DONLEMSONTRADE and best practices."; break;
      case 'Export': prompt = "What are the requirements for exporting goods from Nigeria internationally using DONLEMSONTRADE?"; break;
      case 'Regulations': prompt = "How do Nigerian trade regulations and agreements like AfCFTA affect my business?"; break;
      case 'Home': window.scrollTo({ top: 0, behavior: 'smooth' }); return;
      case 'About': prompt = "Who is DONLEMSONTRADE and what is the mission for Nigerian international trade?"; break;
      default: return;
    }
    setExternalPrompt(prompt);
    setTimeout(() => setExternalPrompt(null), 100);
  };

  return (
    <div className="min-h-screen flex flex-col bg-gray-50 font-sans">
      <Navbar 
        onAction={handleQuickAction} 
        onLoginClick={() => handleOpenLogin()}
        user={userProfile?.name || null}
        onLogout={handleLogout}
      />

      <NewsFeed 
        isOpen={isNewsOpen} 
        onClose={() => setIsNewsOpen(false)} 
      />

      <ContactOverlay
        isOpen={isContactOpen}
        onClose={() => setIsContactOpen(false)}
      />

      <LoginModal 
        isOpen={isLoginModalOpen} 
        onClose={() => {
          setIsLoginModalOpen(false);
          setPrefillName('');
        }} 
        onLogin={handleLogin}
        prefillName={prefillName}
      />

      <header className="bg-white border-b border-gray-100 py-24 relative overflow-hidden">
        {/* Abstract Background Decoration */}
        <div className="absolute top-0 right-0 w-96 h-96 bg-blue-50 rounded-full blur-3xl -mr-48 -mt-48 opacity-60"></div>
        <div className="absolute bottom-0 left-0 w-64 h-64 bg-emerald-50 rounded-full blur-3xl -ml-32 -mb-32 opacity-40"></div>

        <div className="max-w-7xl mx-auto px-4 text-center relative z-10 animate-fade-up">
          {userProfile && (
            <div className="mb-8 inline-flex items-center space-x-3 bg-emerald-50 border border-emerald-100 px-5 py-2.5 rounded-full shadow-sm animate-fade-up stagger-1">
              <span className="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse"></span>
              <span className="text-[10px] font-black text-emerald-700 uppercase tracking-[0.2em]">
                Active Profile: {userProfile.name} | {userProfile.company}
              </span>
            </div>
          )}
          <h1 className="text-5xl md:text-8xl font-black text-blue-900 mb-6 tracking-tighter leading-none animate-fade-up stagger-2">
            DONLEMSON<span className="text-emerald-600">TRADE</span>
          </h1>
          <p className="text-xl md:text-2xl text-gray-500 max-w-3xl mx-auto font-medium leading-relaxed animate-fade-up stagger-3">
            The standard for digital trade intelligence in Nigeria. <br className="hidden md:block" />
            Empowering borders with AI-driven compliance and education.
          </p>

          <div className="mt-12 flex flex-wrap justify-center gap-4 animate-fade-up stagger-3">
            <button 
              onClick={() => handleQuickAction('E-Learning')}
              className="px-8 py-4 bg-blue-900 text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl shadow-blue-900/20 hover:scale-105 transition-transform"
            >
              Access Global College
            </button>
            <button 
              onClick={() => setIsContactOpen(true)}
              className="px-8 py-4 bg-white text-blue-900 border border-gray-200 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-lg hover:bg-gray-50 transition-colors"
            >
              Consult an Expert
            </button>
          </div>
        </div>
      </header>

      <main className="flex-1 space-y-0">
        <div id="college-section" className="animate-fade-up stagger-3">
          <GlobalCollege 
