import React, { useState } from 'react';

const CARRIERS = [
  { name: 'MSC', prefix: ['MEDU'], url: 'https://www.msc.com/en/track-a-shipment' },
  { name: 'Maersk', prefix: ['MAEU', 'MSKU'], url: 'https://www.maersk.com/tracking/' },
  { name: 'CMA CGM', prefix: ['CMAU'], url: 'https://www.cma-cgm.com/ebusiness/tracking' },
  { name: 'Hapag-Lloyd', prefix: ['HLCU'], url: 'https://www.hapag-lloyd.com/en/online-business/track/track-by-container-number.html' },
  { name: 'COSCO', prefix: ['COSU'], url: 'https://lines.coscoshipping.com/track/' },
  { name: 'Ocean Network Express (ONE)', prefix: ['ONEU'], url: 'https://www.one-line.com/en/standard-page/track-trace' },
  { name: 'Evergreen', prefix: ['EGLV'], url: 'https://www.shipmentlink.com/servlet/TDB1_CargoTracking.do' },
  { name: 'Grimaldi', prefix: ['GRIU'], url: 'https://www.grimaldi.napoli.it/en/track_and_trace.html' }
];

const ShipmentTracker: React.FC = () => {
  const [trackingNumber, setTrackingNumber] = useState('');
  const [detectedCarrier, setDetectedCarrier] = useState<typeof CARRIERS[0] | null>(null);

  const handleInputChange = (val: string) => {
    const upperVal = val.toUpperCase();
    setTrackingNumber(upperVal);

    if (upperVal.length >= 4) {
      const prefix = upperVal.substring(0, 4);
      const carrier = CARRIERS.find(c => c.prefix.includes(prefix));
      setDetectedCarrier(carrier || null);
    } else {
      setDetectedCarrier(null);
    }
  };

  const handleTrack = () => {
    if (!trackingNumber) return;

    if (detectedCarrier) {
      window.open(detectedCarrier.url, '_blank');
    } else {
      // Default to a general search or ask user to select if not detected
      window.open(`https://www.track-trace.com/container/${trackingNumber}`, '_blank');
    }
  };

  return (
    <div className="bg-white border border-gray-100 rounded-[3rem] shadow-xl overflow-hidden group">
      <div className="bg-blue-900 p-8 text-white relative">
        <div className="absolute top-0 right-0 p-8 opacity-10">
          <i className="fas fa-radar fa-5x animate-pulse"></i>
        </div>
        <div className="relative z-10">
          <div className="w-12 h-12 bg-emerald-500 rounded-xl flex items-center justify-center mb-4">
            <i className="fas fa-search-location text-xl"></i>
          </div>
          <h3 className="text-2xl font-black uppercase tracking-tighter">Document Tracker</h3>
          <p className="text-blue-200 text-xs font-medium mt-1">Real-time Container & Bill of Lading Status</p>
        </div>
      </div>

      <div className="p-10 space-y-6">
        <div className="relative">
          <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3">Input BL or Container Number</label>
          <input 
            type="text"
            value={trackingNumber}
            onChange={(e) => handleInputChange(e.target.value)}
            placeholder="e.g., MEDU1234567"
            className="w-full bg-slate-50 border border-slate-200 rounded-2xl py-4 px-6 text-blue-900 font-bold placeholder:text-slate-300 focus:outline-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 transition-all"
          />
          {detectedCarrier && (
            <div className="absolute right-4 top-[3.25rem] flex items-center space-x-2 bg-emerald-100 text-emerald-700 px-3 py-1 rounded-full animate-in fade-in zoom-in">
              <span className="text-[9px] font-black uppercase tracking-tight">{detectedCarrier.name} Detected</span>
              <i className="fas fa-check-circle text-[10px]"></i>
            </div>
          )}
        </div>

        <button 
          onClick={handleTrack}
          disabled={!trackingNumber}
          className="w-full bg-blue-900 text-white font-black py-5 rounded-2xl flex items-center justify-center space-x-3 hover:bg-emerald-600 transition-all shadow-xl shadow-blue-900/10 disabled:opacity-50 group active:scale-95"
        >
          <span className="uppercase tracking-[0.2em] text-[10px]">Verify Status</span>
          <i className="fas fa-external-link-alt text-[10px] group-hover:translate-x-1 group-hover:-translate-y-1 transition-transform"></i>
        </button>

        <p className="text-[9px] text-gray-400 font-medium text-center leading-relaxed">
          Supports MSC, Maersk, CMA CGM, COSCO, Grimaldi, and 20+ other lines. 
          <br/>Direct redirection to carrier manifest systems.
        </p>
      </div>
    </div>
  );
};

export default ShipmentTracker;

