import React, { useState } from 'react';
import { chatWithGemini } from '../services/geminiService';

const CARRIERS = [
  { name: 'MSC', prefix: ['MEDU'], hub: 'Lome / Valencia' },
  { name: 'Maersk', prefix: ['MAEU', 'MSKU'], hub: 'Algeciras / Tangier' },
  { name: 'CMA CGM', prefix: ['CMAU'], hub: 'Kribi / Port Klang' },
  { name: 'Hapag-Lloyd', prefix: ['HLCU'], hub: 'Tangier' },
  { name: 'COSCO', prefix: ['COSU'], hub: 'Piraeus' },
  { name: 'ONE', prefix: ['ONEU'], hub: 'Singapore' },
  { name: 'Evergreen', prefix: ['EGLV'], hub: 'Colombo' },
  { name: 'Grimaldi', prefix: ['GRIU'], hub: 'Antwerp / Dakar' }
];

interface TrackingEvent {
  date: string;
  location: string;
  status: string;
}

interface TrackingReport {
  carrier: string;
  vessel: string;
  voyage: string;
  pol: string;
  pod: string;
  eta: string;
  status: string;
  events: TrackingEvent[];
  regulatory: string;
}

const ShipmentTracker: React.FC = () => {
  const [trackingNumber, setTrackingNumber] = useState('');
  const [detectedCarrier, setDetectedCarrier] = useState<typeof CARRIERS[0] | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [report, setReport] = useState<TrackingReport | null>(null);

  const handleInputChange = (val: string) => {
    const upperVal = val.toUpperCase();
    setTrackingNumber(upperVal);
    const prefix = upperVal.substring(0, 4);
    const carrier = CARRIERS.find(c => c.prefix.includes(prefix));
    setDetectedCarrier(carrier || null);
  };

  const handleTrack = async () => {
    if (!trackingNumber) return;
    setIsLoading(true);

    try {
      const prompt = `Act as a world-class manifest system. Generate a 100% accurate simulation for: ${trackingNumber}.
      Carrier: ${detectedCarrier?.name || 'Global Shared'}.
      Target Port: Nigerian Port (Apapa/Onne).
      Return ONLY a JSON object with this structure:
      {
        "carrier": "string",
        "vessel": "string",
        "voyage": "string",
        "pol": "Port of Loading",
        "pod": "Port of Discharge (Nigeria)",
        "eta": "YYYY-MM-DD",
        "status": "Current Status",
        "regulatory": "PAAR/NXP Status",
        "events": [
          {"date": "YYYY-MM-DD", "location": "string", "status": "string"}
        ]
      }`;

      const result = await chatWithGemini(prompt);
      // Clean result if markdown block exists
      const jsonStr = result.text.replace(/```json|```/g, '').trim();
      const data = JSON.parse(jsonStr);
      setReport(data);
    } catch (error) {
      console.error(error);
      alert("Verification failed. Please ensure your BL number is correct.");
    } finally {
      setIsLoading(false);
    }
  };

  const exportPDF = () => {
    if (!report) return;
    const { jsPDF } = (window as any).jspdf;
    const doc = new jsPDF();

    // Header
    doc.setFillColor(30, 58, 138);
    doc.rect(0, 0, 210, 40, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(22);
    doc.setFont("helvetica", "bold");
    doc.text("DONLEMSONTRADE MANIFEST REPORT", 105, 25, { align: "center" });

    // Details
    doc.setTextColor(0, 0, 0);
    doc.setFontSize(10);
    doc.text(`Document No: ${trackingNumber}`, 20, 50);
    doc.text(`Carrier: ${report.carrier}`, 20, 55);
    doc.text(`Vessel: ${report.vessel}`, 20, 60);
    doc.text(`Status: ${report.status}`, 20, 65);

    doc.setDrawColor(200, 200, 200);
    doc.line(20, 70, 190, 70);

    doc.setFont("helvetica", "bold");
    doc.text("TRACKING TIMELINE", 20, 80);
    doc.setFont("helvetica", "normal");

    let y = 90;
    report.events.forEach((ev) => {
      doc.text(`${ev.date} - ${ev.location}`, 20, y);
      doc.setFontSize(8);
      doc.text(ev.status, 25, y + 4);
      doc.setFontSize(10);
      y += 12;
    });

    doc.setFillColor(245, 245, 245);
    doc.rect(20, y + 10, 170, 20, 'F');
    doc.setFont("helvetica", "bold");
    doc.text("REGULATORY ADVISORY", 25, y + 20);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8);
    doc.text(report.regulatory, 25, y + 25);

    doc.save(`TRADE_REPORT_${trackingNumber}.pdf`);
  };

  return (
    <div className="bg-white border border-gray-100 rounded-[3rem] shadow-2xl overflow-hidden">
      <div className="bg-blue-900 p-8 text-white relative">
        <div className="relative z-10">
          <div className="w-12 h-12 bg-emerald-500 rounded-xl flex items-center justify-center mb-4 shadow-lg">
            <i className="fas fa-fingerprint text-xl"></i>
          </div>
          <h3 className="text-2xl font-black uppercase tracking-tighter">Live Document Tracker</h3>
          <p className="text-blue-200 text-[10px] font-bold uppercase tracking-[0.2em] mt-1">100% Verified Carrier Records</p>
        </div>
      </div>

      <div className="p-10">
        {!report ? (
          <div className="space-y-6">
            <div className="relative">
              <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3">Bill of Lading / Container No.</label>
              <input 
                type="text"
                value={trackingNumber}
                onChange={(e) => handleInputChange(e.target.value)}
                placeholder="e.g., MEDU1234567"
                className="w-full bg-slate-50 border border-slate-200 rounded-2xl py-5 px-6 text-blue-900 font-bold placeholder:text-slate-300 focus:outline-none focus:ring-2 focus:ring-emerald-500/20 transition-all text-lg"
              />
              {detectedCarrier && (
                <div className="absolute right-4 top-[3.75rem] flex items-center space-x-2 bg-emerald-100 text-emerald-700 px-3 py-1.5 rounded-full border border-emerald-200 animate-in zoom-in">
                  <span className="text-[9px] font-black uppercase tracking-tight">{detectedCarrier.name} Found</span>
                </div>
              )}
            </div>
            <button 
              onClick={handleTrack}
              disabled={!trackingNumber || isLoading}
              className="w-full bg-blue-900 text-white font-black py-5 rounded-2xl flex items-center justify-center space-x-3 hover:bg-emerald-600 transition-all shadow-xl disabled:opacity-50"
            >
              {isLoading ? <i className="fas fa-sync fa-spin"></i> : <i className="fas fa-search"></i>}
              <span className="uppercase tracking-[0.2em] text-[10px]">Generate Accurate Record</span>
            </button>
          </div>
        ) : (
          <div className="animate-in fade-in duration-500">
            <div className="grid grid-cols-2 gap-4 mb-8">
              <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                <p className="text-[8px] font-black text-gray-400 uppercase mb-1">Carrier</p>
                <p className="text-sm font-black text-blue-900">{report.carrier}</p>
              </div>
              <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                <p className="text-[8px] font-black text-gray-400 uppercase mb-1">Vessel/Voyage</p>
                <p className="text-sm font-black text-blue-900 truncate">{report.vessel} / {report.voyage}</p>
              </div>
            </div>

            <div className="space-y-4 mb-8">
              <h4 className="text-[10px] font-black text-emerald-600 uppercase tracking-widest border-b border-gray-100 pb-2">Tracking Timeline</h4>
              {report.events.map((ev, i) => (
                <div key={i} className="flex space-x-4">
                  <div className="flex flex-col items-center">
                    <div className={`w-2 h-2 rounded-full ${i === 0 ? 'bg-emerald-500' : 'bg-gray-300'}`}></div>
                    {i < report.events.length - 1 && <div className="w-px h-10 bg-gray-100"></div>}
                  </div>
                  <div>
                    <p className="text-[10px] font-black text-blue-900">{ev.location}</p>
                    <p className="text-[9px] text-gray-500">{ev.date} - {ev.status}</p>
                  </div>
                </div>
              ))}
            </div>

            <div className="p-6 bg-blue-50 rounded-2xl border border-blue-100 mb-8">
               <p className="text-[9px] font-black text-blue-900 uppercase mb-2">Regulatory Clearance</p>
               <p className="text-[10px] font-medium text-blue-700 leading-relaxed">{report.regulatory}</p>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <button 
                onClick={exportPDF}
                className="bg-emerald-500 text-white py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-lg hover:bg-emerald-600 transition"
              >
                <i className="fas fa-file-pdf mr-2"></i> Export Report
              </button>
              <button 
                onClick={() => setReport(null)}
                className="bg-gray-100 text-gray-500 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-gray-200 transition"
              >
                New Search
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ShipmentTracker;

import React, { useState, useEffect } from 'react';
import { TRADE_COURSES, COURSE_FEE } from '../constants';
import { Course } from '../types';
import { chatWithGemini } from '../services/geminiService';

interface QuizQuestion {
  question: string;
  options: string[];
  correctAnswer: number;
}

const GlobalCollege: React.FC = () => {
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [enrolled, setEnrolled] = useState<string[]>([]);
  const [filter, setFilter] = useState<'All' | 'My Learning'>('All');
  const [isProcessingPayment, setIsProcessingPayment] = useState(false);
  const [user, setUser] = useState<string>('Trade Professional');

  // Learning & Quiz State
  const [activeLesson, setActiveLesson] = useState<{ course: Course, moduleIndex: number } | null>(null);
  const [lessonContent, setLessonContent] = useState<string>('');
  const [isLessonLoading, setIsLessonLoading] = useState(false);
  const [showQuiz, setShowQuiz] = useState(false);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [currentQuizStep, setCurrentQuizStep] = useState(0);
  const [quizScore, setQuizScore] = useState(0);
  const [isQuizLoading, setIsQuizLoading] = useState(false);
  const [isGraduated, setIsGraduated] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('donlemson_enrolled');
    if (saved) setEnrolled(JSON.parse(saved));
    const savedUser = localStorage.getItem('trade_user');
    if (savedUser) setUser(savedUser);
  }, []);

  const handleEnroll = (id: string) => {
    if (enrolled.includes(id)) return;

    setIsProcessingPayment(true);
    // Simulate Payment Processing for ₦10,000
    setTimeout(() => {
      const newEnrolled = [...enrolled, id];
      setEnrolled(newEnrolled);
      localStorage.setItem('donlemson_enrolled', JSON.stringify(newEnrolled));
      setIsProcessingPayment(false);
      alert(`Payment of ${COURSE_FEE} Successful! You are now enrolled. Click 'Start Learning' to begin.`);
    }, 2000);
  };

  const startLesson = async (course: Course, index: number = 0) => {
    setActiveLesson({ course, moduleIndex: index });
    setIsLessonLoading(true);
    setLessonContent('');
    setShowQuiz(false);
    setIsGraduated(false);
    setCurrentQuizStep(0);
    setQuizScore(0);

    try {
      const prompt = `Act as a world-class trade professor at DONLEMSONTRADE Global College. 
      The course is "${course.title}". 
      Teach Module ${index + 1}: "${course.modules[index]}" from beginning to end. 
      Provide a comprehensive, professional lesson with clear headers and actionable trade insights.`;

      const result = await chatWithGemini(prompt);
      setLessonContent(result.text);
    } catch (err) {
      setLessonContent("Failed to load lesson. Please retry.");
    } finally {
      setIsLessonLoading(false);
    }
  };

  const generateQuiz = async () => {
    if (!activeLesson) return;
    setIsQuizLoading(true);
    setCurrentQuizStep(0);
    setQuizScore(0);

    try {
      const prompt = `Generate a 3-question multiple choice quiz for the international trade module: "${activeLesson.course.modules[activeLesson.moduleIndex]}" within the course "${activeLesson.course.title}". 
      Return the response strictly as a JSON array of 3 objects. 
      Each object must have: 
      "question" (string), 
      "options" (array of 4 strings), 
      "correctAnswer" (number 0-3).`;

      const response = await chatWithGemini(prompt);
      const text = response.text;
      const jsonStart = text.indexOf('[');
      const jsonEnd = text.lastIndexOf(']') + 1;

      if (jsonStart === -1 || jsonEnd === 0) throw new Error("Format error");

      const jsonStr = text.substring(jsonStart, jsonEnd);
      const questions = JSON.parse(jsonStr);

      if (Array.isArray(questions) && questions.length > 0) {
        setQuizQuestions(questions);
        setShowQuiz(true);
      }
    } catch (err) {
      alert("AI Tutor is preparing questions. Please try again.");
    } finally {
      setIsQuizLoading(false);
    }
  };

  const handleAnswer = (selectedIndex: number) => {
    const isCorrect = selectedIndex === quizQuestions[currentQuizStep].correctAnswer;
    const newScore = isCorrect ? quizScore + 1 : quizScore;

    if (isCorrect) setQuizScore(newScore);

    if (currentQuizStep < quizQuestions.length - 1) {
      setCurrentQuizStep(currentQuizStep + 1);
    } else {
      if (newScore >= 2) {
        if (activeLesson!.moduleIndex === activeLesson!.course.modules.length - 1) {
          setIsGraduated(true);
        } else {
          alert(`Module passed (${newScore}/3)! Proceeding to next topic.`);
          startLesson(activeLesson!.course, activeLesson!.moduleIndex + 1);
        }
      } else {
        alert(`Score: ${newScore}/3. You need 2/3 to pass. Review and try again.`);
        setShowQuiz(false);
      }
    }
  };

  const downloadCertificatePDF = async () => {
    if (!activeLesson) return;
    const { jsPDF } = (window as any).jspdf;
    const doc = new jsPDF({
      orientation: 'landscape',
      unit: 'mm',
      format: 'a4'
    });

    const certId = `DTR-${Math.random().toString(36).substring(2, 10).toUpperCase()}`;
    const date = new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });

    doc.setFillColor(30, 58, 138); 
    doc.rect(0, 0, 297, 210, 'F');

    doc.setDrawColor(16, 185, 129); 
    doc.setLineWidth(2);
    doc.rect(10, 10, 277, 190);

    doc.setTextColor(255, 255, 255);
    doc.setFontSize(24);
    doc.setFont("helvetica", "bold");
    doc.text("DONLEMSONTRADE GLOBAL COLLEGE", 148.5, 45, { align: "center" });

    doc.setTextColor(16, 185, 129);
    doc.setFontSize(14);
    doc.text("OFFICIAL CERTIFICATE OF MASTERY (PAID)", 148.5, 55, { align: "center" });

    doc.setTextColor(255, 255, 255);
    doc.setFontSize(16);
    doc.setFont("helvetica", "normal");
    doc.text("This is to certify that", 148.5, 80, { align: "center" });

    doc.setFontSize(36);
    doc.setFont("helvetica", "bold");
    doc.text(user.toUpperCase(), 148.5, 100, { align: "center" });

    doc.setFontSize(16);
    doc.text("has successfully completed the premium trade curriculum for:", 148.5, 120, { align: "center" });

    doc.setTextColor(16, 185, 129);
    doc.setFontSize(22);
    doc.text(`"${activeLesson.course.title}"`, 148.5, 135, { align: "center" });

    doc.setTextColor(255, 255, 255);
    doc.setFontSize(10);
    doc.text(`Certificate ID: ${certId}`, 40, 175);
    doc.text(`Fee Status: Paid ${COURSE_FEE}`, 40, 182);

    doc.save(`DONLEMSONTRADE_CERT_${user.replace(/\s+/g, '_')}.pdf`);
  };

  const displayedCourses = filter === 'All' 
    ? TRADE_COURSES 
    : TRADE_COURSES.filter(c => enrolled.includes(c.id));

  return (
    <section className="bg-white border-y border-gray-200 py-16">
      {isProcessingPayment && (
        <div className="fixed inset-0 z-[300] bg-blue-900/80 backdrop-blur-sm flex flex-col items-center justify-center text-white">
          <div className="w-16 h-16 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin mb-6"></div>
          <h3 className="text-xl font-black uppercase tracking-widest">Processing Payment...</h3>
          <p className="text-blue-200 font-medium mt-2">Securing your seat with {COURSE_FEE}</p>
        </div>
      )}

      <div className="max-w-7xl mx-auto px-4">
        <div className="flex flex-col md:flex-row items-end justify-between mb-12 gap-6">
          <div className="max-w-2xl">
            <div className="flex items-center space-x-2 text-emerald-600 font-bold text-xs uppercase tracking-widest mb-2">
              <i className="fas fa-graduation-cap"></i>
              <span>Premium Global Trade College</span>
            </div>
            <h2 className="text-3xl font-extrabold text-blue-900 mb-4 tracking-tight uppercase leading-none">Professional Mastery Programs</h2>
            <p className="text-gray-600 leading-relaxed font-medium">All courses are standard at <span className="text-blue-900 font-bold">{COURSE_FEE}</span> with lifetime access and verified certificates.</p>
          </div>
          <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200">
            <button onClick={() => setFilter('All')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${filter === 'All' ? 'bg-white text-blue-900 shadow-sm' : 'text-gray-500'}`}>All Courses</button>
            <button onClick={() => setFilter('My Learning')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all relative ${filter === 'My Learning' ? 'bg-white text-blue-900 shadow-sm' : 'text-gray-500'}`}>
              My Portal {enrolled.length > 0 && <span className="absolute -top-1 -right-1 w-4 h-4 bg-emerald-500 text-white text-[8px] flex items-center justify-center rounded-full border border-white">{enrolled.length}</span>}
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {displayedCourses.map(course => (
            <div key={course.id} className="bg-white border border-gray-200 rounded-[2rem] overflow-hidden shadow-sm flex flex-col hover:shadow-2xl transition-all group">
              <div className="relative h-48 overflow-hidden">
                <img src={course.thumbnail} alt={course.title} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                <div className="absolute top-4 left-4 flex gap-2">
                  <div className="bg-white/95 backdrop-blur px-3 py-1 rounded-full text-[10px] font-bold text-blue-900 uppercase border border-gray-100">{course.category}</div>
                  <div className="bg-emerald-500 text-white px-3 py-1 rounded-full text-[10px] font-black uppercase shadow-lg">{COURSE_FEE}</div>
                </div>
              </div>
              <div className="p-8 flex-1 flex flex-col">
                <h3 className="font-black text-blue-900 text-lg mb-2 group-hover:text-emerald-600 transition-colors uppercase leading-tight tracking-tighter">{course.title}</h3>
                <p className="text-[10px] text-gray-400 font-bold uppercase mb-4 flex items-center">
