                <div className="mt-auto pt-6 border-t border-gray-100 flex items-center justify-between">
                  <button onClick={() => setSelectedCourse(course)} className="text-[10px] font-black text-blue-900 hover:text-emerald-600 uppercase tracking-widest transition">View Curriculum</button>
                  {enrolled.includes(course.id) ? (
                    <button onClick={() => startLesson(course, 0)} className="bg-emerald-600 text-white px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-emerald-700 transition-all shadow-xl">Resume</button>
