                          key={i}
                          onClick={() => handleAnswer(i)}
                          className="w-full text-left p-8 rounded-3xl border-2 border-slate-100 hover:border-emerald-500 hover:bg-emerald-50 transition-all group flex items-center justify-between bg-slate-50/30"
                        >
                          <div className="flex items-center space-x-8">
