                    <span className="leading-tight uppercase tracking-tight">{mod}</span>
                  </div>
                ))}
              </div>
              <div className="flex gap-4">
                <button onClick={() => setSelectedCourse(null)} className="flex-1 bg-slate-50 text-gray-400 font-black text-[10px] uppercase tracking-widest py-5 rounded-2xl hover:bg-slate-100 transition">Discard</button>
                {enrolled.includes(selectedCourse.id) ? (
                   <button onClick={() => { startLesson(selectedCourse, 0); setSelectedCourse(null); }} className="flex-[2] bg-emerald-600 text-white font-black text-[10px] uppercase tracking-widest py-5 rounded-2xl shadow-xl hover:bg-emerald-700 transition-all">Launch Learning</button>
