                    <span className="w-10 h-10 rounded-xl bg-white text-blue-900 flex items-center justify-center text-[10px] font-black border border-slate-200 group-hover:bg-blue-900 group-hover:text-white transition-all shrink-0 shadow-sm">{i+1}</span>
                    <span className="leading-tight uppercase tracking-tight">{mod}</span>
                  </div>
                ))}
              </div>
