                   <button onClick={() => { startLesson(selectedCourse, 0); setSelectedCourse(null); }} className="flex-[2] bg-emerald-600 text-white font-black text-[10px] uppercase tracking-widest py-5 rounded-2xl shadow-xl hover:bg-emerald-700 transition-all">Launch Learning</button>
                ) : (
                  <button onClick={() => { handleEnrollInitiation(selectedCourse); setSelectedCourse(null); }} className={`flex-[2] ${selectedCourse.isFree ? 'bg-emerald-600' : 'bg-blue-900'} text-white font-black text-[10px] uppercase tracking-widest py-5 rounded-2xl shadow-xl hover:opacity-90 transition-all flex items-center justify-center space-x-3`}>
                    <span>{selectedCourse.isFree ? 'Get Free Access' : `Pay ${COURSE_FEE} & Enroll`}</span>
                    <i className={`fas ${selectedCourse.isFree ? 'fa-unlock' : 'fa-lock'} text-[10px]`}></i>
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </section>
  );
};

export default GlobalCollege;

import React, { useState, useEffect } from 'react';
import { TRADE_COURSES, COURSE_FEE } from '../constants';
import { Course } from '../types';
import { chatWithGemini } from '../services/geminiService';

interface QuizQuestion {
  question: string;
  options: string[];
  correctAnswer: number;
}

const GlobalCollege: React.FC = () => {
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [enrolled, setEnrolled] = useState<string[]>([]);
  const [filter, setFilter] = useState<'All' | 'My Learning'>('All');
  const [isProcessingPayment, setIsProcessingPayment] = useState(false);
  const [showPaymentModal, setShowPaymentModal] = useState<Course | null>(null);
  const [user, setUser] = useState<string>('Trade Professional');

  // Learning & Quiz State
  const [activeLesson, setActiveLesson] = useState<{ course: Course, moduleIndex: number } | null>(null);
  const [lessonContent, setLessonContent] = useState<string>('');
  const [isLessonLoading, setIsLessonLoading] = useState(false);
  const [showQuiz, setShowQuiz] = useState(false);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [currentQuizStep, setCurrentQuizStep] = useState(0);
  const [quizScore, setQuizScore] = useState(0);
  const [isQuizLoading, setIsQuizLoading] = useState(false);
  const [isGraduated, setIsGraduated] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('donlemson_enrolled');
    if (saved) setEnrolled(JSON.parse(saved));
    const savedUser = localStorage.getItem('trade_user');
    if (savedUser) setUser(savedUser);
  }, []);

  const handleEnrollInitiation = (course: Course) => {
    if (enrolled.includes(course.id)) return;

    if (course.isFree) {
      completeEnrollment(course.id);
      return;
    }

    setShowPaymentModal(course);
  };

  const completeEnrollment = (courseId: string) => {
    const newEnrolled = [...enrolled, courseId];
    setEnrolled(newEnrolled);
    localStorage.setItem('donlemson_enrolled', JSON.stringify(newEnrolled));
  };

  const handleConfirmPayment = () => {
    if (!showPaymentModal) return;

    setIsProcessingPayment(true);
    setShowPaymentModal(null);

    // Simulate Payment Verification
    setTimeout(() => {
      completeEnrollment(showPaymentModal.id);
      setIsProcessingPayment(false);
      alert(`Payment Confirmed for ${showPaymentModal.title}! You now have full access.`);
    }, 2500);
  };

  const startLesson = async (course: Course, index: number = 0) => {
    setActiveLesson({ course, moduleIndex: index });
    setIsLessonLoading(true);
    setLessonContent('');
    setShowQuiz(false);
    setIsGraduated(false);
    setCurrentQuizStep(0);
    setQuizScore(0);

    try {
      const prompt = `Act as a world-class trade professor at DONLEMSONTRADE Global College. 
      The course is "${course.title}". 
      Teach Module ${index + 1}: "${course.modules[index]}" from beginning to end. 
      Provide a comprehensive, professional lesson with clear headers and actionable trade insights.`;

      const result = await chatWithGemini(prompt);
      setLessonContent(result.text);
    } catch (err) {
      setLessonContent("Failed to load lesson. Please retry.");
    } finally {
      setIsLessonLoading(false);
    }
  };

  const generateQuiz = async () => {
    if (!activeLesson) return;
    setIsQuizLoading(true);
    setCurrentQuizStep(0);
    setQuizScore(0);

    try {
      const prompt = `Generate a 3-question multiple choice quiz for the international trade module: "${activeLesson.course.modules[activeLesson.moduleIndex]}" within the course "${activeLesson.course.title}". 
      Return the response strictly as a JSON array of 3 objects. 
      Each object must have: 
      "question" (string), 
      "options" (array of 4 strings), 
      "correctAnswer" (number 0-3).`;

      const response = await chatWithGemini(prompt);
      const text = response.text;
      const jsonStart = text.indexOf('[');
      const jsonEnd = text.lastIndexOf(']') + 1;

      if (jsonStart === -1 || jsonEnd === 0) throw new Error("Format error");

      const jsonStr = text.substring(jsonStart, jsonEnd);
      const questions = JSON.parse(jsonStr);

      if (Array.isArray(questions) && questions.length > 0) {
        setQuizQuestions(questions);
        setShowQuiz(true);
      }
    } catch (err) {
      alert("AI Tutor is preparing questions. Please try again.");
    } finally {
      setIsQuizLoading(false);
    }
  };

  const handleAnswer = (selectedIndex: number) => {
    const isCorrect = selectedIndex === quizQuestions[currentQuizStep].correctAnswer;
    const newScore = isCorrect ? quizScore + 1 : quizScore;

    if (isCorrect) setQuizScore(newScore);

    if (currentQuizStep < quizQuestions.length - 1) {
      setCurrentQuizStep(currentQuizStep + 1);
    } else {
      if (newScore >= 2) {
        if (activeLesson!.moduleIndex === activeLesson!.course.modules.length - 1) {
          setIsGraduated(true);
        } else {
          alert(`Module passed (${newScore}/3)! Proceeding to next topic.`);
          startLesson(activeLesson!.course, activeLesson!.moduleIndex + 1);
        }
      } else {
        alert(`Score: ${newScore}/3. You need 2/3 to pass. Review and try again.`);
        setShowQuiz(false);
      }
    }
  };

  const downloadCertificatePDF = async () => {
    if (!activeLesson) return;
    const { jsPDF } = (window as any).jspdf;
    const doc = new jsPDF({
      orientation: 'landscape',
      unit: 'mm',
      format: 'a4'
    });

    const certId = `DTR-${Math.random().toString(36).substring(2, 10).toUpperCase()}`;

    doc.setFillColor(30, 58, 138); 
    doc.rect(0, 0, 297, 210, 'F');
    doc.setDrawColor(16, 185, 129); 
    doc.setLineWidth(2);
    doc.rect(10, 10, 277, 190);

    doc.setTextColor(255, 255, 255);
    doc.setFontSize(24);
    doc.setFont("helvetica", "bold");
    doc.text("DONLEMSONTRADE GLOBAL COLLEGE", 148.5, 45, { align: "center" });

    doc.setTextColor(16, 185, 129);
    doc.setFontSize(14);
    doc.text(activeLesson.course.isFree ? "OFFICIAL CERTIFICATE OF COMPLETION" : "OFFICIAL CERTIFICATE OF MASTERY (PAID)", 148.5, 55, { align: "center" });

    doc.setTextColor(255, 255, 255);
    doc.setFontSize(16);
    doc.setFont("helvetica", "normal");
    doc.text("This is to certify that", 148.5, 80, { align: "center" });

    doc.setFontSize(36);
    doc.setFont("helvetica", "bold");
    doc.text(user.toUpperCase(), 148.5, 100, { align: "center" });

    doc.setFontSize(16);
    doc.text("has successfully completed the premium trade curriculum for:", 148.5, 120, { align: "center" });

    doc.setTextColor(16, 185, 129);
    doc.setFontSize(22);
    doc.text(`"${activeLesson.course.title}"`, 148.5, 135, { align: "center" });

    doc.setTextColor(255, 255, 255);
    doc.setFontSize(10);
    doc.text(`Certificate ID: ${certId}`, 40, 175);
    doc.text(`Status: ${activeLesson.course.isFree ? 'Foundation Tier' : `Paid ${COURSE_FEE}`}`, 40, 182);

    doc.save(`DONLEMSONTRADE_CERT_${user.replace(/\s+/g, '_')}.pdf`);
  };

  const displayedCourses = filter === 'All' 
    ? TRADE_COURSES 
    : TRADE_COURSES.filter(c => enrolled.includes(c.id));

  return (
    <section className="bg-white border-y border-gray-200 py-16">
      {/* Loading Screen */}
      {isProcessingPayment && (
        <div className="fixed inset-0 z-[300] bg-blue-900/80 backdrop-blur-sm flex flex-col items-center justify-center text-white">
          <div className="w-16 h-16 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin mb-6"></div>
          <h3 className="text-xl font-black uppercase tracking-widest">Verifying Payment...</h3>
          <p className="text-blue-200 font-medium mt-2 text-center">Checking 3000454101 (Kuda Bank) for transaction.</p>
        </div>
      )}

      {/* Manual Payment Modal */}
      {showPaymentModal && (
        <div className="fixed inset-0 z-[250] bg-blue-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95">
            <div className="bg-blue-900 p-8 text-white text-center">
              <h3 className="text-2xl font-black uppercase tracking-tighter">Enrollment Payment</h3>
              <p className="text-blue-300 text-xs font-bold mt-1 uppercase tracking-widest">Premium Course Access</p>
            </div>
            <div className="p-10 space-y-8">
              <div className="text-center">
                <p className="text-gray-400 text-[10px] font-black uppercase tracking-widest mb-2">Amount to Pay</p>
                <div className="text-4xl font-black text-blue-900">{COURSE_FEE}</div>
              </div>

              <div className="bg-slate-50 border border-slate-100 p-6 rounded-3xl space-y-4">
                <div className="flex justify-between items-center">
                  <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Bank</span>
                  <span className="text-sm font-black text-blue-900">Kuda Bank</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Account Number</span>
                  <span className="text-lg font-black text-emerald-600">3000454101</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Account Name</span>
                  <span className="text-sm font-black text-blue-900">JOELRIT VENTURES</span>
                </div>
              </div>

              <div className="space-y-3">
                <button 
                  onClick={handleConfirmPayment}
                  className="w-full bg-blue-900 text-white font-black py-4 rounded-2xl shadow-xl hover:bg-emerald-600 transition-all uppercase text-[10px] tracking-widest"
                >
