      {selectedCourse && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-blue-900/40 backdrop-blur-md">
          {/* Syllabus Modal: Adjusted to h-[50%] and offset slightly from the top to show background content */}
          <div className="bg-white w-full max-w-xl h-[50%] mt-20 rounded-[3rem] shadow-2xl overflow-hidden border border-white/20 animate-in zoom-in-95 flex flex-col">
            <div className="bg-blue-900 p-8 text-white relative shrink-0">
              <button onClick={() => setSelectedCourse(null)} className="absolute top-8 right-10 text-white/30 hover:text-white transition"><i className="fas fa-times text-2xl"></i></button>
              <div className="flex items-center space-x-3 mb-2">
                 <span className={`${selectedCourse.isFree ? 'bg-emerald-500' : 'bg-blue-800'} text-[9px] font-black uppercase px-3 py-1 rounded-full shadow-lg`}>
                   {selectedCourse.isFree ? 'Foundation Curriculum' : 'Premium Curriculum'}
                 </span>
                 <span className="text-[9px] font-black uppercase tracking-widest text-blue-300">{selectedCourse.level}</span>
              </div>
              <h3 className="font-black text-2xl tracking-tighter leading-none uppercase truncate">{selectedCourse.title}</h3>
            </div>
            <div className="p-8 flex-1 flex flex-col overflow-hidden">
              <div className="space-y-3 mb-6 flex-1 overflow-y-auto pr-2 custom-scrollbar">
                {selectedCourse.modules.map((mod, i) => (
                  <div key={i} className="flex items-center text-xs font-black text-blue-900 space-x-4 group bg-slate-50 p-3 rounded-2xl border border-transparent hover:border-emerald-200 hover:bg-white transition-all">
                    <span className="w-8 h-8 rounded-xl bg-white text-blue-900 flex items-center justify-center text-[9px] font-black border border-slate-200 group-hover:bg-blue-900 group-hover:text-white transition-all shrink-0 shadow-sm">{i+1}</span>
                    <span className="leading-tight uppercase tracking-tight">{mod}</span>
                  </div>
                ))}
              </div>
              <div className="flex gap-4 shrink-0">
                <button onClick={() => setSelectedCourse(null)} className="flex-1 bg-slate-50 text-gray-400 font-black text-[9px] uppercase tracking-widest py-4 rounded-2xl hover:bg-slate-100 transition">Discard</button>
                {enrolled.includes(selectedCourse.id) ? (
                   <button onClick={() => { startLesson(selectedCourse, 0); setSelectedCourse(null); }} className="flex-[2] bg-emerald-600 text-white font-black text-[9px] uppercase tracking-widest py-4 rounded-2xl shadow-xl hover:bg-emerald-700 transition-all">Launch Learning</button>
                ) : (
                  <button onClick={() => { handleEnrollInitiation(selectedCourse); setSelectedCourse(null); }} className={`flex-[2] ${selectedCourse.isFree ? 'bg-emerald-600' : 'bg-blue-900'} text-white font-black text-[9px] uppercase tracking-widest py-4 rounded-2xl shadow-xl hover:opacity-90 transition-all flex items-center justify-center space-x-3`}>
                    <span>{selectedCourse.isFree ? 'Get Free Access' : `Pay ${COURSE_FEE} & Enroll`}</span>
                    <i className={`fas ${selectedCourse.isFree ? 'fa-unlock' : 'fa-lock'} text-[10px]`}></i>
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </section>
  );
};

export default GlobalCollege;

import React, { useState, useEffect } from 'react';
import { TRADE_COURSES, COURSE_FEE } from '../constants';
import { Course } from '../types';
import { chatWithGemini } from '../services/geminiService';

interface QuizQuestion {
  question: string;
  options: string[];
  correctAnswer: number;
}

const GlobalCollege: React.FC = () => {
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [enrolled, setEnrolled] = useState<string[]>([]);
  const [filter, setFilter] = useState<'All' | 'My Learning'>('All');
  const [isProcessingPayment, setIsProcessingPayment] = useState(false);
  const [showPaymentModal, setShowPaymentModal] = useState<Course | null>(null);
  const [user, setUser] = useState<string>('Trade Professional');

  // Learning & Quiz State
  const [activeLesson, setActiveLesson] = useState<{ course: Course, moduleIndex: number } | null>(null);
  const [lessonContent, setLessonContent] = useState<string>('');
  const [isLessonLoading, setIsLessonLoading] = useState(false);
  const [showQuiz, setShowQuiz] = useState(false);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [currentQuizStep, setCurrentQuizStep] = useState(0);
  const [quizScore, setQuizScore] = useState(0);
  const [isQuizLoading, setIsQuizLoading] = useState(false);
  const [isGraduated, setIsGraduated] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('donlemson_enrolled');
    if (saved) setEnrolled(JSON.parse(saved));
    const savedUser = localStorage.getItem('trade_user');
    if (savedUser) setUser(savedUser);
  }, []);

  const handleEnrollInitiation = (course: Course) => {
    if (enrolled.includes(course.id)) return;

    if (course.isFree) {
      completeEnrollment(course.id);
      return;
    }

    setShowPaymentModal(course);
  };

  const completeEnrollment = (courseId: string) => {
    const newEnrolled = [...enrolled, courseId];
    setEnrolled(newEnrolled);
    localStorage.setItem('donlemson_enrolled', JSON.stringify(newEnrolled));
  };

  const handleConfirmPayment = () => {
    if (!showPaymentModal) return;

    setIsProcessingPayment(true);
    setShowPaymentModal(null);

    // Simulate Payment Verification
    setTimeout(() => {
      completeEnrollment(showPaymentModal.id);
      setIsProcessingPayment(false);
      alert(`Payment Confirmed for ${showPaymentModal.title}! You now have full access.`);
    }, 2500);
  };

  const startLesson = async (course: Course, index: number = 0) => {
    setActiveLesson({ course, moduleIndex: index });
    setIsLessonLoading(true);
    setLessonContent('');
    setShowQuiz(false);
    setIsGraduated(false);
    setCurrentQuizStep(0);
    setQuizScore(0);

    try {
      const prompt = `Act as a world-class trade professor at DONLEMSONTRADE Global College. 
      The course is "${course.title}". 
      Teach Module ${index + 1}: "${course.modules[index]}" from beginning to end. 
      Provide a comprehensive, professional lesson with clear headers and actionable trade insights.`;

      const result = await chatWithGemini(prompt);
      setLessonContent(result.text);
    } catch (err) {
      setLessonContent("Failed to load lesson. Please retry.");
    } finally {
      setIsLessonLoading(false);
    }
  };

  const generateQuiz = async () => {
    if (!activeLesson) return;
    setIsQuizLoading(true);
    setCurrentQuizStep(0);
    setQuizScore(0);

    try {
      const prompt = `Generate a 3-question multiple choice quiz for the international trade module: "${activeLesson.course.modules[activeLesson.moduleIndex]}" within the course "${activeLesson.course.title}". 
      Return the response strictly as a JSON array of 3 objects. 
      Each object must have: 
      "question" (string), 
      "options" (array of 4 strings), 
      "correctAnswer" (number 0-3).`;

      const response = await chatWithGemini(prompt);
      const text = response.text;
      const jsonStart = text.indexOf('[');
      const jsonEnd = text.lastIndexOf(']') + 1;

      if (jsonStart === -1 || jsonEnd === 0) throw new Error("Format error");

      const jsonStr = text.substring(jsonStart, jsonEnd);
      const questions = JSON.parse(jsonStr);

      if (Array.isArray(questions) && questions.length > 0) {
        setQuizQuestions(questions);
        setShowQuiz(true);
      }
    } catch (err) {
      alert("AI Tutor is preparing questions. Please try again.");
    } finally {
      setIsQuizLoading(false);
    }
  };

  const handleAnswer = (selectedIndex: number) => {
    const isCorrect = selectedIndex === quizQuestions[currentQuizStep].correctAnswer;
    const newScore = isCorrect ? quizScore + 1 : quizScore;

    if (isCorrect) setQuizScore(newScore);

    if (currentQuizStep < quizQuestions.length - 1) {
      setCurrentQuizStep(currentQuizStep + 1);
    } else {
      if (newScore >= 2) {
        if (activeLesson!.moduleIndex === activeLesson!.course.modules.length - 1) {
          setIsGraduated(true);
        } else {
          alert(`Module passed (${newScore}/3)! Proceeding to next topic.`);
          startLesson(activeLesson!.course, activeLesson!.moduleIndex + 1);
        }
      } else {
        alert(`Score: ${newScore}/3. You need 2/3 to pass. Review and try again.`);
        setShowQuiz(false);
      }
    }
  };

  const downloadCertificatePDF = async () => {
    if (!activeLesson) return;
    const { jsPDF } = (window as any).jspdf;
    const doc = new jsPDF({
      orientation: 'landscape',
      unit: 'mm',
      format: 'a4'
    });

    const certId = `DTR-${Math.random().toString(36).substring(2, 10).toUpperCase()}`;

    doc.setFillColor(30, 58, 138); 
    doc.rect(0, 0, 297, 210, 'F');
    doc.setDrawColor(16, 185, 129); 
    doc.setLineWidth(2);
    doc.rect(10, 10, 277, 190);

    doc.setTextColor(255, 255, 255);
    doc.setFontSize(24);
    doc.setFont("helvetica", "bold");
    doc.text("DONLEMSONTRADE GLOBAL COLLEGE", 148.5, 45, { align: "center" });

    doc.setTextColor(16, 185, 129);
    doc.setFontSize(14);
    doc.text(activeLesson.course.isFree ? "OFFICIAL CERTIFICATE OF COMPLETION" : "OFFICIAL CERTIFICATE OF MASTERY (PAID)", 148.5, 55, { align: "center" });

    doc.setTextColor(255, 255, 255);
    doc.setFontSize(16);
    doc.setFont("helvetica", "normal");
    doc.text("This is to certify that", 148.5, 80, { align: "center" });

    doc.setFontSize(36);
    doc.setFont("helvetica", "bold");
    doc.text(user.toUpperCase(), 148.5, 100, { align: "center" });

    doc.setFontSize(16);
    doc.text("has successfully completed the premium trade curriculum for:", 148.5, 120, { align: "center" });

    doc.setTextColor(16, 185, 129);
    doc.setFontSize(22);
    doc.text(`"${activeLesson.course.title}"`, 148.5, 135, { align: "center" });

    doc.setTextColor(255, 255, 255);
    doc.setFontSize(10);
    doc.text(`Certificate ID: ${certId}`, 40, 175);
    doc.text(`Status: ${activeLesson.course.isFree ? 'Foundation Tier' : `Paid ${COURSE_FEE}`}`, 40, 182);

    doc.save(`DONLEMSONTRADE_CERT_${user.replace(/\s+/g, '_')}.pdf`);
  };

  const displayedCourses = filter === 'All' 
    ? TRADE_COURSES 
    : TRADE_COURSES.filter(c => enrolled.includes(c.id));

  return (
    <section className="bg-white border-y border-gray-200 py-16">
      {/* Loading Screen */}
      {isProcessingPayment && (
        <div className="fixed inset-0 z-[300] bg-blue-900/80 backdrop-blur-sm flex flex-col items-center justify-center text-white">
          <div className="w-16 h-16 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin mb-6"></div>
          <h3 className="text-xl font-black uppercase tracking-widest">Verifying Payment...</h3>
          <p className="text-blue-200 font-medium mt-2 text-center">Checking 3000454101 (Kuda Bank) for transaction.</p>
        </div>
      )}

      {/* Manual Payment Modal */}
      {showPaymentModal && (
        <div className="fixed inset-0 z-[250] bg-blue-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95">
            <div className="bg-blue-900 p-8 text-white text-center">
              <h3 className="text-2xl font-black uppercase tracking-tighter">Enrollment Payment</h3>
              <p className="text-blue-300 text-xs font-bold mt-1 uppercase tracking-widest">Premium Course Access</p>
            </div>
            <div className="p-10 space-y-8">
              <div className="text-center">
                <p className="text-gray-400 text-[10px] font-black uppercase tracking-widest mb-2">Amount to Pay</p>
                <div className="text-4xl font-black text-blue-900">{COURSE_FEE}</div>
              </div>

              <div className="bg-slate-50 border border-slate-100 p-6 rounded-3xl space-y-4">
                <div className="flex justify-between items-center">
                  <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Bank</span>
                  <span className="text-sm font-black text-blue-900">Kuda Bank</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Account Number</span>
                  <span className="text-lg font-black text-emerald-600">3000454101</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Account Name</span>
                  <span className="text-sm font-black text-blue-900">JOELRIT VENTURES</span>
                </div>
              </div>

              <div className="space-y-3">
                <button 
                  onClick={handleConfirmPayment}
                  className="w-full bg-blue-900 text-white font-black py-4 rounded-2xl shadow-xl hover:bg-emerald-600 transition-all uppercase text-[10px] tracking-widest"
                >
                  I have made the payment
                </button>
                <button 
                  onClick={() => setShowPaymentModal(null)}
                  className="w-full bg-slate-100 text-slate-400 font-black py-4 rounded-2xl uppercase text-[10px] tracking-widest hover:bg-slate-200 transition"
                >
                  Cancel Enrollment
                </button>
              </div>
              <p className="text-[9px] text-gray-400 text-center font-bold">Your payment will be manually verified by the trade desk before access is granted.</p>
            </div>
          </div>
        </div>
      )}

      <div className="max-w-7xl mx-auto px-4">
        <div className="flex flex-col md:flex-row items-end justify-between mb-12 gap-6">
          <div className="max-w-2xl">
            <div className="flex items-center space-x-2 text-emerald-600 font-bold text-xs uppercase tracking-widest mb-2">
              <i className="fas fa-graduation-cap"></i>
              <span>Premium Global Trade College</span>
            </div>
            <h2 className="text-3xl font-extrabold text-blue-900 mb-4 tracking-tight uppercase leading-none">Global Learning Portals</h2>
            <p className="text-gray-600 leading-relaxed font-medium">Explore our <b>Foundation (Free)</b> and <b>Professional ({COURSE_FEE})</b> mastery programs.</p>
          </div>
          <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200">
            <button onClick={() => setFilter('All')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${filter === 'All' ? 'bg-white text-blue-900 shadow-sm' : 'text-gray-500'}`}>All Courses</button>
            <button onClick={() => setFilter('My Learning')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all relative ${filter === 'My Learning' ? 'bg-white text-blue-900 shadow-sm' : 'text-gray-500'}`}>
              My Portal {enrolled.length > 0 && <span className="absolute -top-1 -right-1 w-4 h-4 bg-emerald-500 text-white text-[8px] flex items-center justify-center rounded-full border border-white">{enrolled.length}</span>}
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {displayedCourses.map(course => (
            <div key={course.id} className="bg-white border border-gray-200 rounded-[2rem] overflow-hidden shadow-sm flex flex-col hover:shadow-2xl transition-all group">
              <div className="relative h-48 overflow-hidden">
                <img src={course.thumbnail} alt={course.title} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                <div className="absolute top-4 left-4 flex gap-2">
                  <div className="bg-white/95 backdrop-blur px-3 py-1 rounded-full text-[10px] font-bold text-blue-900 uppercase border border-gray-100">{course.category}</div>
                  <div className={`${course.isFree ? 'bg-emerald-600' : 'bg-blue-900'} text-white px-3 py-1 rounded-full text-[10px] font-black uppercase shadow-lg`}>
                    {course.isFree ? 'FREE' : COURSE_FEE}
                  </div>
                </div>
              </div>
              <div className="p-8 flex-1 flex flex-col">
                <h3 className="font-black text-blue-900 text-lg mb-2 group-hover:text-emerald-600 transition-colors uppercase leading-tight tracking-tighter">{course.title}</h3>
                <p className="text-[10px] text-gray-400 font-bold uppercase mb-4 flex items-center">
                  <i className="fas fa-certificate mr-2 text-emerald-500"></i> {course.instructor}
                </p>
                <div className="mt-auto pt-6 border-t border-gray-100 flex items-center justify-between">
                  <button onClick={() => setSelectedCourse(course)} className="text-[10px] font-black text-blue-900 hover:text-emerald-600 uppercase tracking-widest transition">View Syllabus</button>
                  {enrolled.includes(course.id) ? (
                    <button onClick={() => startLesson(course, 0)} className="bg-emerald-600 text-white px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-emerald-700 transition-all shadow-xl">Start Learning</button>
                  ) : (
                    <button onClick={() => handleEnrollInitiation(course)} className={`${course.isFree ? 'bg-emerald-600' : 'bg-blue-900'} text-white px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest hover:opacity-90 transition-all shadow-xl`}>
                      {course.isFree ? 'Get Access' : 'Enroll Now'}
                    </button>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {activeLesson && (
        <div className="fixed inset-0 z-[200] bg-white flex flex-col animate-in slide-in-from-bottom duration-500">
          <div className="bg-blue-900 px-6 py-4 text-white flex items-center justify-between shadow-xl">
            <div className="flex items-center space-x-6">
              <button onClick={() => setActiveLesson(null)} className="w-10 h-10 rounded-full hover:bg-white/10 flex items-center justify-center transition">
                <i className="fas fa-times"></i>
              </button>
              <div>
                <h2 className="font-black text-xs uppercase tracking-widest">{activeLesson.course.title}</h2>
                <div className="flex items-center space-x-3 mt-1">
                  <div className="w-32 h-1.5 bg-blue-800 rounded-full overflow-hidden">
                    <div 
                      className="h-full bg-emerald-400 transition-all duration-700" 
                      style={{ width: `${((activeLesson.moduleIndex + (showQuiz ? 1 : 0.5)) / activeLesson.course.modules.length) * 100}%` }}
                    ></div>
                  </div>
                  <span className="text-[9px] text-blue-300 font-black uppercase tracking-widest">
                    {showQuiz ? 'Assessment Phase' : `Topic ${activeLesson.moduleIndex + 1} of ${activeLesson.course.modules.length}`}
                  </span>
                </div>
              </div>
            </div>
            <div className="bg-emerald-500 text-white px-4 py-1 rounded-full text-[9px] font-black uppercase shadow-lg">
              {activeLesson.course.isFree ? 'Foundation Tier' : 'Premium Access'}
            </div>
          </div>

          <div className="flex-1 flex overflow-hidden">
            <div className="hidden lg:block w-80 border-r border-gray-100 bg-slate-50 overflow-y-auto p-8">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] mb-8 flex items-center">
                <i className="fas fa-book-open mr-2"></i> Course Journey
              </h3>
              <div className="space-y-3">
                {activeLesson.course.modules.map((mod, i) => (
                  <button 
                    key={i}
                    onClick={() => !isLessonLoading && !isQuizLoading && startLesson(activeLesson.course, i)}
                    className={`w-full text-left p-5 rounded-2xl text-[11px] font-black flex items-center space-x-4 transition-all border uppercase ${
                      activeLesson.moduleIndex === i 
                      ? 'bg-white border-emerald-200 shadow-xl text-blue-900' 
                      : 'text-gray-400 border-transparent hover:bg-white hover:text-gray-600'
                    }`}
                  >
                    <span className={`w-8 h-8 rounded-xl flex items-center justify-center shrink-0 border ${
                      activeLesson.moduleIndex > i ? 'bg-emerald-500 text-white border-emerald-500' : 
                      activeLesson.moduleIndex === i ? 'bg-blue-900 text-white border-blue-900 shadow-lg' : 'bg-gray-100 border-gray-200'
                    }`}>
                      {activeLesson.moduleIndex > i ? <i className="fas fa-check text-[10px]"></i> : i + 1}
                    </span>
                    <span className="leading-tight">{mod}</span>
                  </button>
                ))}
              </div>
            </div>

            <div className="flex-1 overflow-y-auto bg-white p-8 md:p-16">
              <div className="max-w-4xl mx-auto">
                {isGraduated ? (
                  <div className="text-center py-24 bg-gradient-to-br from-emerald-50 to-white rounded-[3rem] border border-emerald-100 shadow-inner px-12">
                    <div className="w-32 h-32 bg-emerald-500 text-white rounded-full flex items-center justify-center text-5xl mx-auto mb-10 animate-bounce shadow-2xl">
                      <i className="fas fa-graduation-cap"></i>
                    </div>
                    <h1 className="text-5xl font-black text-blue-900 mb-6 tracking-tighter uppercase leading-none">Learning Goal Achieved</h1>
                    <p className="text-blue-800/60 font-bold mb-12 max-w-lg mx-auto text-lg leading-relaxed">Congratulations, {user}! You have successfully completed {activeLesson.course.title}.</p>
                    <div className="flex flex-col md:flex-row items-center justify-center gap-6">
                      <button 
                        onClick={downloadCertificatePDF}
                        className="w-full md:w-auto bg-blue-900 text-white px-12 py-5 rounded-3xl font-black uppercase tracking-widest text-[11px] hover:bg-emerald-600 transition-all shadow-2xl active:scale-95"
                      >
                        Download Certificate <i className="fas fa-file-pdf ml-2"></i>
                      </button>
                      <button onClick={() => setActiveLesson(null)} className="font-black text-[11px] uppercase tracking-widest text-gray-400 hover:text-blue-900 transition">Return to Portal</button>
                    </div>
                  </div>
                ) : showQuiz ? (
                  <div className="animate-in fade-in slide-in-from-right duration-500">
                    <div className="flex flex-col md:flex-row md:items-center justify-between mb-12 gap-4">
                       <div className="flex items-center space-x-4">
                          <span className="bg-emerald-500 text-white px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest">Mastery Assessment</span>
                          <span className="text-blue-900 text-[10px] font-black uppercase tracking-widest">Step {currentQuizStep + 1} of 3</span>
                       </div>
                       <div className="text-[10px] font-black text-emerald-600 bg-emerald-50 px-4 py-2 rounded-xl border border-emerald-100 uppercase">
                         Pass Score: 2/3 | Current: {quizScore}
                       </div>
                    </div>

                    <div className="mb-12">
                      <h2 className="text-4xl font-black text-blue-900 leading-tight tracking-tighter uppercase">
                        {quizQuestions[currentQuizStep].question}
                      </h2>
                    </div>

                    <div className="grid grid-cols-1 gap-4">
                      {quizQuestions[currentQuizStep].options.map((option, i) => (
                        <button 
                          key={i}
                          onClick={() => handleAnswer(i)}
                          className="w-full text-left p-8 rounded-3xl border-2 border-slate-100 hover:border-emerald-500 hover:bg-emerald-50 transition-all group flex items-center justify-between bg-slate-50/30"
                        >
                          <div className="flex items-center space-x-8">
                            <span className="w-12 h-12 rounded-2xl bg-white border border-slate-200 flex items-center justify-center font-black text-blue-900 group-hover:bg-emerald-500 group-hover:text-white transition-all shadow-sm">
                              {String.fromCharCode(65 + i)}
                            </span>
                            <span className="text-slate-800 font-black text-xl group-hover:text-emerald-900 leading-tight">{option}</span>
                          </div>
                          <i className="fas fa-arrow-right text-slate-200 group-hover:text-emerald-500 transition-all"></i>
                        </button>
                      ))}
                    </div>
                  </div>
                ) : (
                  <div className="animate-in fade-in duration-700">
                    <div className="mb-12 flex items-center justify-between">
                      <div>
                        <span className="text-[10px] font-black text-emerald-600 uppercase tracking-[0.5em] mb-3 block">Lecture Session</span>
                        <h1 className="text-5xl font-black text-blue-900 tracking-tighter leading-none mb-4 uppercase">{activeLesson.course.modules[activeLesson.moduleIndex]}</h1>
                        <div className="h-2 w-24 bg-blue-900 rounded-full"></div>
