          </form>

          <div className="relative py-8">
            <div className="absolute inset-0 flex items-center">
              <div className="w-full border-t border-gray-100"></div>
            </div>
            <div className="relative flex justify-center text-[10px]">
              <span className="bg-white px-4 text-gray-400 font-bold uppercase tracking-widest">Or Continue With</span>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-3">
            <button 
              onClick={() => handleSocialLogin('Google')}
              disabled={isLoading !== null}
              type="button" 
              className="flex flex-col items-center justify-center space-y-1.5 border border-gray-200 rounded-xl py-3 hover:bg-gray-50 hover:border-gray-300 transition group"
