import React, { useState, useRef, useEffect } from 'react';
import { Message } from '../types';
import { chatWithGemini, editTradeImage } from '../services/geminiService';
import LiveVoiceChat from './LiveVoiceChat';
import LoginModal from './LoginModal';

interface ChatInterfaceProps {
  externalPrompt?: string | null;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({ externalPrompt }) => {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: '1',
      role: 'assistant',
      content: "Hello! I'm your DONLEMSONTRADE global consultant. How can I assist with your international trade queries today?",
      timestamp: Date.now(),
    }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [imageMime, setImageMime] = useState<string>('');
  const [pendingSignup, setPendingSignup] = useState<{fullName: string, email: string, courseName: string} | null>(null);
  const [isSignupModalOpen, setIsSignupModalOpen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading]);

  useEffect(() => {
    if (externalPrompt) {
      handleSend(externalPrompt);
    }
  }, [externalPrompt]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
        setImageMime(file.type);
      };
      reader.readAsDataURL(file);
    }
  };

  const finalizeSignup = (name: string) => {
    localStorage.setItem('trade_user', name);
    if (pendingSignup?.courseName) {
      const currentEnrolled = JSON.parse(localStorage.getItem('donlemson_enrolled') || '[]');
      // Simple logic to find course ID or just tag it
      const courseId = pendingSignup.courseName.toLowerCase().replace(/\s+/g, '-');
      if (!currentEnrolled.includes(courseId)) {
        localStorage.setItem('donlemson_enrolled', JSON.stringify([...currentEnrolled, courseId]));
      }
    }

    const successMsg: Message = {
      id: Date.now().toString(),
      role: 'assistant',
      content: `Excellent! You are all set, ${name}. I've successfully signed you up and enrolled you in ${pendingSignup?.courseName || 'your selected course'}. You can now access your dashboard.`,
      timestamp: Date.now(),
    };
    setMessages(prev => [...prev, successMsg]);
    setPendingSignup(null);
    window.dispatchEvent(new Event('storage'));
  };

  const handleSend = async (overrideInput?: string) => {
    const messageText = overrideInput || input;
    if (!messageText.trim() && !selectedImage) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: messageText,
      image: selectedImage || undefined,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMessage]);
    if (!overrideInput) setInput('');
    setIsLoading(true);

    try {
      if (selectedImage) {
        const result = await editTradeImage(messageText || "Analyze this trade document or product.", selectedImage, imageMime);
        const assistantMessage: Message = {
          id: (Date.now() + 1).toString(),
          role: 'assistant',
          content: result.feedbackText || "I've processed the image for you.",
          image: result.imageUrl || undefined,
          timestamp: Date.now(),
        };
        setMessages(prev => [...prev, assistantMessage]);
      } else {
        const result = await chatWithGemini(messageText);

        if (result.toolCalls && result.toolCalls.length > 0) {
          for (const call of result.toolCalls) {
            if (call.name === 'signUpUser') {
              const { fullName, email, courseName } = call.args;
              setPendingSignup({ fullName, email, courseName });
              setIsSignupModalOpen(true);

              const assistantMessage: Message = {
                id: (Date.now() + 1).toString(),
                role: 'assistant',
                content: `I've prepared your registration for the "${courseName}" course. Please verify the details in the secure window that just appeared. Once you confirm, you'll be signed in automatically.`,
                timestamp: Date.now(),
              };
              setMessages(prev => [...prev, assistantMessage]);
            }
          }
        } else {
          const assistantMessage: Message = {
            id: (Date.now() + 1).toString(),
            role: 'assistant',
            content: result.text,
            sources: result.sources,
            timestamp: Date.now(),
          };
          setMessages(prev => [...prev, assistantMessage]);
        }
      }
    } catch (error) {
      console.error(error);
      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: "I'm sorry, I hit a snag. Could you try asking again?",
        timestamp: Date.now(),
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
      setSelectedImage(null);
    }
  };

  return (
    <div className="flex flex-col h-[600px] bg-white rounded-xl shadow-lg overflow-hidden border border-gray-200">
      <LoginModal 
        isOpen={isSignupModalOpen}
        onClose={() => setIsSignupModalOpen(false)}
        onLogin={finalizeSignup}
        initialData={pendingSignup || undefined}
      />

      {/* Header */}
      <div className="bg-blue-900 px-6 py-4 flex items-center justify-between shadow-sm">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 rounded-full bg-blue-800 flex items-center justify-center text-white border border-blue-700">
            <i className="fas fa-robot text-lg"></i>
          </div>
          <div>
            <h3 className="font-bold text-white text-sm">Trade support</h3>
            <p className="text-[10px] text-blue-300 font-bold uppercase tracking-widest">Global Intelligence</p>
          </div>
        </div>
        <LiveVoiceChat />
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-gray-50/30">
        {messages.map((m) => (
          <div key={m.id} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] ${m.role === 'user' ? 'ml-8' : 'mr-8'}`}>
              <div className={`px-4 py-3 rounded-xl shadow-sm ${
                m.role === 'user' 
                  ? 'bg-blue-900 text-white rounded-tr-none' 
                  : 'bg-white text-gray-800 rounded-tl-none border border-gray-200'
              }`}>
                {m.image && (
                  <div className="mb-3 rounded-lg overflow-hidden border border-gray-100">
                    <img src={m.image} alt="Trade Content" className="max-h-60 w-full object-contain" />
                  </div>
                )}
                <div className="text-[14px] leading-relaxed whitespace-pre-wrap">
                  {m.content}
                </div>

                {m.sources && m.sources.length > 0 && (
                  <div className="mt-3 pt-3 border-t border-gray-100">
                    <p className="text-[9px] font-bold text-blue-600 uppercase tracking-widest mb-2">Sources</p>
                    <div className="flex flex-wrap gap-2">
                      {m.sources.map((src, idx) => (
                        <a key={idx} href={src.uri} target="_blank" rel="noreferrer" className="bg-blue-50 text-blue-800 text-[10px] px-2 py-1 rounded border border-blue-100 hover:bg-blue-100 transition">
                          {src.title}
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
              <p className={`text-[9px] mt-1 text-gray-400 font-medium ${m.role === 'user' ? 'text-right' : 'text-left'}`}>
                {new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </p>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-white px-4 py-3 rounded-xl border border-gray-200">
              <div className="flex space-x-1">
                <div className="w-1.5 h-1.5 bg-blue-300 rounded-full animate-bounce"></div>
                <div className="w-1.5 h-1.5 bg-blue-300 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                <div className="w-1.5 h-1.5 bg-blue-300 rounded-full animate-bounce [animation-delay:0.4s]"></div>
              </div>
            </div>
          </div>
        )}
        <div ref={chatEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-4 bg-white border-t border-gray-200">
        <div className="flex items-center space-x-2">
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="w-10 h-10 flex items-center justify-center rounded-lg bg-gray-50 border border-gray-200 text-gray-500 hover:text-blue-900 transition"
          >
            <i className="fas fa-camera"></i>
          </button>
          <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*" />
          <div className="flex-1 relative">
            <input 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Type your message..."
              className="w-full bg-gray-50 border border-gray-200 rounded-lg py-2.5 pl-4 pr-12 focus:outline-none focus:ring-1 focus:ring-blue-900 focus:bg-white transition-all text-sm"
            />
            <button 
              onClick={() => handleSend()}
              disabled={isLoading || (!input.trim() && !selectedImage)}
              className="absolute right-1.5 top-1.5 w-7 h-7 bg-blue-900 text-white rounded flex items-center justify-center disabled:opacity-50"
            >
              <i className="fas fa-paper-plane text-[10px]"></i>
            </button>
          </div>
        </div>
        {selectedImage && (
          <div className="mt-3 relative inline-block">
            <img src={selectedImage} alt="Preview" className="h-16 w-16 object-cover rounded border border-gray-200" />
            <button onClick={() => setSelectedImage(null)} className="absolute -top-2 -right-2 bg-red-500 text-white w-4 h-4 rounded-full flex items-center justify-center text-[8px]">
              <i className="fas fa-times"></i>
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default ChatInterface;

import React, { useState, useEffect } from 'react';

interface LoginModalProps {
  isOpen: boolean;
  onClose: () => void;
  onLogin: (name: string) => void;
  initialData?: { fullName: string; email: string; courseName?: string };
}

const LoginModal: React.FC<LoginModalProps> = ({ isOpen, onClose, onLogin, initialData }) => {
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState<string | null>(null);

  useEffect(() => {
    if (initialData) {
      setFullName(initialData.fullName || '');
      setEmail(initialData.email || '');
    }
  }, [initialData, isOpen]);

  if (!isOpen) return null;

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading('form');
    setTimeout(() => {
      onLogin(fullName);
      setIsLoading(null);
      onClose();
    }, 1500);
  };

  const handleSocialLogin = (provider: string) => {
    setIsLoading(provider);
    setTimeout(() => {
      onLogin(`${fullName || 'User'} (${provider})`);
      setIsLoading(null);
      onClose();
    }, 2000);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-blue-900/60 backdrop-blur-md animate-in fade-in duration-300">
      <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl overflow-hidden transform transition-all animate-in zoom-in-95 duration-200">

        {isLoading && isLoading !== 'form' && (
          <div className="absolute inset-0 z-10 bg-white/90 backdrop-blur-sm flex flex-col items-center justify-center p-8 text-center">
            <div className="w-12 h-12 border-4 border-blue-900 border-t-transparent rounded-full animate-spin mb-4"></div>
            <h3 className="text-lg font-bold text-blue-900 uppercase tracking-tighter">Connecting to {isLoading}...</h3>
            <p className="text-gray-500 text-sm">Please wait while we verify your credentials with the provider.</p>
          </div>
        )}

        <div className="bg-blue-900 p-8 text-center relative">
          <button 
            onClick={onClose}
            className="absolute top-4 right-4 text-blue-300 hover:text-white transition"
          >
            <i className="fas fa-times text-lg"></i>
          </button>
          <div className="w-16 h-16 bg-white/10 rounded-2xl flex items-center justify-center mx-auto mb-4 border border-white/20 shadow-inner">
            <i className={`fas ${initialData ? 'fa-user-plus text-emerald-400' : 'fa-shield-alt text-emerald-400'} text-3xl`}></i>
          </div>
          <h2 className="text-2xl font-bold text-white tracking-tight">
            {initialData ? 'Confirm Registration' : 'Trade Portal Login'}
          </h2>
          <p className="text-blue-200 text-sm mt-1 font-medium">
            {initialData ? `Finalize your enrollment in ${initialData.courseName}` : 'Access your global trade dashboard'}
          </p>
        </div>

        <div className="p-8">
          {initialData && (
            <div className="mb-6 p-4 bg-emerald-50 border border-emerald-100 rounded-xl">
              <p className="text-[10px] font-black text-emerald-700 uppercase tracking-widest mb-1">Information from Assistant</p>
              <p className="text-xs text-emerald-800 font-medium italic">"I've pre-filled your details. Please check if they are correct before confirming."</p>
            </div>
          )}

          <form onSubmit={handleFormSubmit} className="space-y-5">
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-2">Full Name</label>
              <div className="relative group">
                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-blue-600 transition-colors">
                  <i className="fas fa-user"></i>
                </span>
                <input 
                  required
                  type="text" 
                  value={fullName}
                  onChange={(e) => setFullName(e.target.value)}
                  placeholder="Enter your full name"
                  className="w-full bg-gray-50 border border-gray-200 rounded-xl py-3.5 pl-11 pr-4 focus:outline-none focus:ring-2 focus:ring-blue-900/10 focus:border-blue-900 transition-all text-sm"
