import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";
import { SYSTEM_PROMPT } from "../constants";

const getAIClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
};

export const chatWithGemini = async (prompt: string, history: any[] = []) => {
  const ai = getAIClient();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_PROMPT,
      tools: [
        { googleSearch: {} }
      ],
      temperature: 0.1,
    },
  });

  return {
    text: response.text || "I'm processing your request...",
    toolCalls: response.functionCalls || [],
    sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || 'Source',
      uri: chunk.web?.uri || ''
    })).filter((s: any) => s.uri) || []
  };
};

export const editTradeImage = async (prompt: string, base64Image: string, mimeType: string) => {
  const ai = getAIClient();
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Image.split(',')[1],
            mimeType: mimeType,
          },
        },
        {
          text: `You are an expert for Nigerian trade documents. Analyze this image and respond IMMEDIATELY with facts. User request: ${prompt}. If not trade-related, decline politely. DO NOT use filler phrases like 'In the context of trade'.`,
        },
      ],
    },
  });

  let imageUrl = '';
  let feedbackText = '';

  for (const part of response.candidates?.[0]?.content.parts || []) {
    if (part.inlineData) {
      imageUrl = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    } else if (part.text) {
      feedbackText = part.text;
    }
  }

  return { imageUrl, feedbackText };
};

import React, { useState, useEffect } from 'react';
import { chatWithGemini } from '../services/geminiService';

interface NewsArticle {
  title: string;
  summary: string;
  source: string;
  date: string;
  category: 'Local' | 'International' | 'Policy';
  url: string;
}

const NewsSection: React.FC<{ isOpen: boolean; onClose: () => void }> = ({ isOpen, onClose }) => {
  const [news, setNews] = useState<NewsArticle[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    if (isOpen) {
      fetchNews();
    }
  }, [isOpen]);

  const fetchNews = async () => {
    setIsLoading(true);
    try {
      const prompt = `Provide the latest (last 7 days) international trade news, specific Nigerian trade updates, and new trade policies (like CBN circulars, Customs CET tariffs, or AfCFTA updates). 
      Format the response as a JSON array of objects. Each object should have: 
      "title", "summary" (2 sentences), "source", "date", "category" (either 'Local', 'International', or 'Policy'), and "url".`;

      const result = await chatWithGemini(prompt);
      const jsonStr = result.text.replace(/```json|```/g, '').trim();
      const data = JSON.parse(jsonStr);
      setNews(Array.isArray(data) ? data : []);
    } catch (error) {
      console.error("Failed to fetch news:", error);
    } finally {
      setIsLoading(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[200] bg-white overflow-y-auto animate-in slide-in-from-right duration-500">
      <div className="sticky top-0 bg-blue-900 text-white p-6 flex items-center justify-between shadow-xl z-10">
        <div className="flex items-center space-x-4">
          <button onClick={onClose} className="w-10 h-10 rounded-full hover:bg-white/10 flex items-center justify-center transition">
            <i className="fas fa-arrow-left"></i>
          </button>
          <div>
            <h2 className="text-xl font-black uppercase tracking-tighter">Trade Intelligence Hub</h2>
            <p className="text-[10px] text-blue-300 font-bold uppercase tracking-widest">Live News & Policy Updates</p>
          </div>
        </div>
        <button onClick={fetchNews} className="text-xs font-bold uppercase tracking-widest bg-emerald-600 px-4 py-2 rounded-lg hover:bg-emerald-700 transition">
          <i className="fas fa-sync-alt mr-2"></i> Refresh
        </button>
      </div>

      <div className="max-w-5xl mx-auto px-6 py-12">
        {isLoading ? (
          <div className="space-y-8">
            {[1, 2, 3].map(i => (
              <div key={i} className="animate-pulse bg-slate-50 p-8 rounded-[2rem] border border-slate-100">
                <div className="h-4 bg-slate-200 rounded w-1/4 mb-4"></div>
                <div className="h-8 bg-slate-200 rounded w-3/4 mb-4"></div>
                <div className="h-4 bg-slate-200 rounded w-full mb-2"></div>
                <div className="h-4 bg-slate-200 rounded w-5/6"></div>
              </div>
            ))}
          </div>
        ) : (
          <div className="grid grid-cols-1 gap-8">
            {news.map((item, idx) => (
              <div key={idx} className="bg-white border border-gray-100 rounded-[2.5rem] p-8 shadow-sm hover:shadow-xl transition-all group flex flex-col md:flex-row gap-8">
                <div className="md:w-1/4">
                  <div className={`inline-block px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest mb-4 ${
                    item.category === 'Policy' ? 'bg-red-100 text-red-700' :
                    item.category === 'Local' ? 'bg-emerald-100 text-emerald-700' : 'bg-blue-100 text-blue-700'
                  }`}>
                    {item.category}
                  </div>
                  <p className="text-xs font-bold text-gray-400 block mb-1">{item.date}</p>
                  <p className="text-[10px] font-black text-blue-900 uppercase tracking-tighter">{item.source}</p>
                </div>
                <div className="md:w-3/4">
                  <h3 className="text-2xl font-black text-blue-900 mb-4 group-hover:text-emerald-600 transition-colors leading-tight">
                    {item.title}
                  </h3>
                  <p className="text-gray-500 font-medium mb-6 leading-relaxed">
                    {item.summary}
                  </p>
                  <a 
                    href={item.url} 
                    target="_blank" 
                    rel="noopener noreferrer"
                    className="inline-flex items-center text-[10px] font-black uppercase tracking-widest text-blue-900 hover:text-emerald-600 transition"
                  >
                    Read Full Article <i className="fas fa-external-link-alt ml-2"></i>
                  </a>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

