import React, { useState, useEffect, useRef } from 'react';
import { TRADE_COURSES, COURSE_FEE } from '../constants';
import { Course } from '../types';
import { chatWithGemini } from '../services/geminiService';
import { GoogleGenAI, Modality } from "@google/genai";

interface QuizQuestion {
  question: string;
  options: string[];
  correctAnswer: number;
}

const GlobalCollege: React.FC = () => {
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [enrolled, setEnrolled] = useState<string[]>([]);
  const [filter, setFilter] = useState<'All' | 'My Learning'>('All');
  const [isProcessingPayment, setIsProcessingPayment] = useState(false);
  const [showPaymentModal, setShowPaymentModal] = useState<Course | null>(null);
  const [user, setUser] = useState<string>('Trade Professional');

  // Learning & Quiz State
  const [activeLesson, setActiveLesson] = useState<{ course: Course, moduleIndex: number } | null>(null);
  const [lessonContent, setLessonContent] = useState<string>('');
  const [isLessonLoading, setIsLessonLoading] = useState(false);
  const [showQuiz, setShowQuiz] = useState(false);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [currentQuizStep, setCurrentQuizStep] = useState(0);
  const [quizScore, setQuizScore] = useState(0);
  const [isQuizLoading, setIsQuizLoading] = useState(false);
  const [isGraduated, setIsGraduated] = useState(false);

  // Audio State
  const [isAudioLoading, setIsAudioLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isPaused, setIsPaused] = useState(false);

  const audioBufferRef = useRef<AudioBuffer | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const startTimeRef = useRef<number>(0);
  const pauseOffsetRef = useRef<number>(0);

  useEffect(() => {
    const saved = localStorage.getItem('donlemson_enrolled');
    if (saved) setEnrolled(JSON.parse(saved));
    const savedUser = localStorage.getItem('trade_user');
    if (savedUser) setUser(savedUser);

    return () => {
      stopAudioCompletely();
    };
  }, []);

  const stopAudioCompletely = () => {
    if (audioSourceRef.current) {
      audioSourceRef.current.stop();
      audioSourceRef.current = null;
    }
    setIsPlaying(false);
    setIsPaused(false);
    pauseOffsetRef.current = 0;
  };

  const toggleAudio = async (text: string) => {
    if (isPlaying) {
      // Pause logic
      if (audioSourceRef.current) {
        audioSourceRef.current.stop();
        audioSourceRef.current = null;
      }
      pauseOffsetRef.current += audioContextRef.current ? audioContextRef.current.currentTime - startTimeRef.current : 0;
      setIsPlaying(false);
      setIsPaused(true);
      return;
    }

    if (audioBufferRef.current) {
      // Resume logic
      startPlayback(pauseOffsetRef.current);
      return;
    }

    // Fetch new audio logic
    setIsAudioLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Act as a professional trade professor. Read this lesson content clearly and enthusiastically: ${text.substring(0, 1500)}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        if (!audioContextRef.current) {
          audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }

        const binaryString = atob(base64Audio);
        const len = binaryString.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
          bytes[i] = binaryString.charCodeAt(i);
        }

        const dataInt16 = new Int16Array(bytes.buffer);
        const frameCount = dataInt16.length;
        const buffer = audioContextRef.current.createBuffer(1, frameCount, 24000);
        const channelData = buffer.getChannelData(0);
        for (let i = 0; i < frameCount; i++) {
          channelData[i] = dataInt16[i] / 32768.0;
        }

        audioBufferRef.current = buffer;
        pauseOffsetRef.current = 0;
        startPlayback(0);
      }
    } catch (err) {
      console.error("Audio generation failed:", err);
    } finally {
      setIsAudioLoading(false);
    }
  };

  const startPlayback = (offset: number) => {
    if (!audioContextRef.current || !audioBufferRef.current) return;

    const source = audioContextRef.current.createBufferSource();
    source.buffer = audioBufferRef.current;
    source.connect(audioContextRef.current.destination);

    source.onended = () => {
      // If it ended naturally (not via stop() for pause)
      if (audioSourceRef.current === source) {
        setIsPlaying(false);
        setIsPaused(false);
        pauseOffsetRef.current = 0;
        audioSourceRef.current = null;
      }
    };

    const playTime = Math.max(0, offset);
    source.start(0, playTime);

    startTimeRef.current = audioContextRef.current.currentTime;
    audioSourceRef.current = source;
    setIsPlaying(true);
    setIsPaused(false);
  };

  const handleEnrollInitiation = (course: Course) => {
    if (enrolled.includes(course.id)) return;
    if (course.isFree) {
      completeEnrollment(course.id);
      return;
    }
    setShowPaymentModal(course);
  };

  const completeEnrollment = (courseId: string) => {
    const newEnrolled = [...enrolled, courseId];
    setEnrolled(newEnrolled);
    localStorage.setItem('donlemson_enrolled', JSON.stringify(newEnrolled));
  };

  const handleConfirmPayment = () => {
    if (!showPaymentModal) return;
    setIsProcessingPayment(true);
    setShowPaymentModal(null);
    setTimeout(() => {
      completeEnrollment(showPaymentModal.id);
      setIsProcessingPayment(false);
      alert(`Payment Confirmed for ${showPaymentModal.title}! You now have full access.`);
    }, 2500);
  };

  const startLesson = async (course: Course, index: number = 0) => {
    stopAudioCompletely();
    audioBufferRef.current = null;
    setActiveLesson({ course, moduleIndex: index });
    setIsLessonLoading(true);
    setLessonContent('');
    setShowQuiz(false);
    setIsGraduated(false);
    setCurrentQuizStep(0);
    setQuizScore(0);

    try {
      const prompt = `Act as a world-class trade professor at DONLEMSONTRADE Global College. 
      The course is "${course.title}". 
      Teach Module ${index + 1}: "${course.modules[index]}" from beginning to end with extreme detail. 
      Include sections on: 
      1. Theoretical background.
      2. Practical application in Nigeria.
      3. Critical compliance checkpoints.
      4. Professional advice for traders.
      Make the content very detailed, at least 600 words.`;

      const result = await chatWithGemini(prompt);
      setLessonContent(result.text);
    } catch (err) {
      setLessonContent("Failed to load lesson. Please retry.");
    } finally {
      setIsLessonLoading(false);
    }
  };

  const generateQuiz = async () => {
    if (!activeLesson) return;
    setIsQuizLoading(true);
    setCurrentQuizStep(0);
    setQuizScore(0);

    try {
      const prompt = `Generate a 3-question multiple choice quiz for the international trade module: "${activeLesson.course.modules[activeLesson.moduleIndex]}" within the course "${activeLesson.course.title}". 
      Return the response strictly as a JSON array of 3 objects. 
      Each object must have: 
      "question" (string), 
      "options" (array of 4 strings), 
      "correctAnswer" (number 0-3).`;

      const response = await chatWithGemini(prompt);
      const text = response.text;
      const jsonStart = text.indexOf('[');
      const jsonEnd = text.lastIndexOf(']') + 1;
      const jsonStr = text.substring(jsonStart, jsonEnd);
      const questions = JSON.parse(jsonStr);

      if (Array.isArray(questions)) {
        setQuizQuestions(questions);
        setShowQuiz(true);
      }
    } catch (err) {
      alert("AI Tutor is preparing questions. Please try again.");
    } finally {
      setIsQuizLoading(false);
    }
  };

  const handleAnswer = (selectedIndex: number) => {
    const isCorrect = selectedIndex === quizQuestions[currentQuizStep].correctAnswer;
    const newScore = isCorrect ? quizScore + 1 : quizScore;
    if (isCorrect) setQuizScore(newScore);

    if (currentQuizStep < quizQuestions.length - 1) {
      setCurrentQuizStep(currentQuizStep + 1);
    } else {
      if (newScore >= 2) {
        if (activeLesson!.moduleIndex === activeLesson!.course.modules.length - 1) {
          setIsGraduated(true);
        } else {
          alert(`Module passed (${newScore}/3)! Proceeding to next topic.`);
          startLesson(activeLesson!.course, activeLesson!.moduleIndex + 1);
        }
      } else {
        alert(`Score: ${newScore}/3. You need 2/3 to pass. Review and try again.`);
        setShowQuiz(false);
      }
    }
  };

  const downloadCertificatePDF = async () => {
    if (!activeLesson) return;
    const { jsPDF } = (window as any).jspdf;
    const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
    doc.setFillColor(30, 58, 138); 
    doc.rect(0, 0, 297, 210, 'F');
    doc.setDrawColor(16, 185, 129); 
    doc.setLineWidth(2);
    doc.rect(10, 10, 277, 190);
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(24);
    doc.setFont("helvetica", "bold");
    doc.text("DONLEMSONTRADE GLOBAL COLLEGE", 148.5, 45, { align: "center" });
    doc.setTextColor(16, 185, 129);
    doc.setFontSize(14);
    doc.text(activeLesson.course.isFree ? "OFFICIAL CERTIFICATE OF COMPLETION" : "OFFICIAL CERTIFICATE OF MASTERY (PAID)", 148.5, 55, { align: "center" });
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(16);
    doc.setFont("helvetica", "normal");
    doc.text("This is to certify that", 148.5, 80, { align: "center" });
    doc.setFontSize(36);
    doc.setFont("helvetica", "bold");
    doc.text(user.toUpperCase(), 148.5, 100, { align: "center" });
    doc.setFontSize(16);
    doc.text("has successfully completed the premium trade curriculum for:", 148.5, 120, { align: "center" });
    doc.setTextColor(16, 185, 129);
    doc.setFontSize(22);
    doc.text(`"${activeLesson.course.title}"`, 148.5, 135, { align: "center" });
    doc.save(`DONLEMSONTRADE_CERT_${user.replace(/\s+/g, '_')}.pdf`);
  };

  const displayedCourses = filter === 'All' ? TRADE_COURSES : TRADE_COURSES.filter(c => enrolled.includes(c.id));

  return (
    <section className="bg-white border-y border-gray-200 py-16">
      {isProcessingPayment && (
        <div className="fixed inset-0 z-[300] bg-blue-900/80 backdrop-blur-sm flex flex-col items-center justify-center text-white">
          <div className="w-16 h-16 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin mb-6"></div>
          <h3 className="text-xl font-black uppercase tracking-widest">Verifying Payment...</h3>
        </div>
      )}

      {showPaymentModal && (
        <div className="fixed inset-0 z-[250] bg-blue-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 p-10 space-y-8">
            <h3 className="text-2xl font-black text-center text-blue-900 uppercase">Enrollment Payment</h3>
            <div className="text-4xl font-black text-center text-emerald-600">{COURSE_FEE}</div>
            <div className="bg-slate-50 p-6 rounded-3xl text-sm font-bold text-blue-900 space-y-2">
              <p>Bank: Kuda Bank</p>
              <p>Account: 3000454101</p>
              <p>Name: JOELRIT VENTURES</p>
            </div>
            <button onClick={handleConfirmPayment} className="w-full bg-blue-900 text-white font-black py-4 rounded-2xl uppercase tracking-widest text-xs">Confirm Payment</button>
            <button onClick={() => setShowPaymentModal(null)} className="w-full text-gray-400 font-bold uppercase text-xs">Cancel</button>
          </div>
        </div>
      )}

      <div className="max-w-7xl mx-auto px-4">
        <div className="flex flex-col md:flex-row items-end justify-between mb-12 gap-6">
          <div className="max-w-2xl">
            <h2 className="text-4xl font-black text-blue-900 uppercase">Global Trade College</h2>
            <p className="text-gray-600 font-medium">Detailed syllabus, AI-powered lessons, and <b>Audio-enabled learning</b>.</p>
          </div>
          <div className="flex bg-gray-100 p-1 rounded-xl">
            <button onClick={() => setFilter('All')} className={`px-6 py-2 rounded-lg text-sm font-bold ${filter === 'All' ? 'bg-white shadow-sm' : ''}`}>All</button>
            <button onClick={() => setFilter('My Learning')} className={`px-6 py-2 rounded-lg text-sm font-bold ${filter === 'My Learning' ? 'bg-white shadow-sm' : ''}`}>Portal</button>
          </div>
