          <div className="bg-blue-900 px-6 py-4 text-white flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <button onClick={() => setActiveLesson(null)} className="hover:text-emerald-400 transition-colors"><i className="fas fa-times"></i></button>
              <h2 className="font-black text-xs uppercase">{activeLesson.course.title}</h2>
            </div>
            <div className="flex items-center space-x-4">
              <button 
                onClick={() => toggleAudio(lessonContent)}
                disabled={isAudioLoading || !lessonContent}
                className={`flex items-center space-x-2 px-6 py-2 rounded-full transition-all shadow-lg ${
                  isPlaying ? 'bg-orange-500 hover:bg-orange-600' : 'bg-emerald-500 hover:bg-emerald-600'
                } disabled:opacity-50 active:scale-95`}
              >
                {isAudioLoading ? (
                  <i className="fas fa-spinner fa-spin"></i>
                ) : isPlaying ? (
                  <i className="fas fa-pause"></i>
                ) : (
                  <i className="fas fa-play"></i>
                )}
                <span className="text-[10px] font-black uppercase">
                  {isAudioLoading ? 'Generating...' : isPlaying ? 'Pause Audio' : isPaused ? 'Resume Audio' : 'Listen to Lesson'}
                </span>
              </button>
              {isPaused && (
                 <button 
                  onClick={stopAudioCompletely}
                  className="w-10 h-10 bg-slate-700 text-white rounded-full flex items-center justify-center hover:bg-red-500 transition-colors"
                  title="Stop and Reset"
                 >
                   <i className="fas fa-stop text-[10px]"></i>
                 </button>
              )}
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-8 md:p-16">
            <div className="max-w-4xl mx-auto">
              {isGraduated ? (
                <div className="text-center py-20 bg-emerald-50 rounded-[3rem] p-12">
                  <h1 className="text-4xl font-black text-blue-900 uppercase">Graduated!</h1>
                  <p className="text-gray-500 font-medium mt-4">You have mastered the curriculum. Your official certificate is ready for download.</p>
                  <button onClick={downloadCertificatePDF} className="mt-8 bg-blue-900 text-white px-10 py-5 rounded-3xl font-black uppercase shadow-xl hover:bg-emerald-600 transition-colors">Download Certificate</button>
                </div>
              ) : showQuiz ? (
                <div className="space-y-8 animate-in slide-in-from-right">
                  <div className="flex justify-between items-center mb-4">
                    <span className="text-[10px] font-black text-blue-900 uppercase tracking-widest">Question {currentQuizStep + 1} of {quizQuestions.length}</span>
                    <span className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Score: {quizScore}</span>
                  </div>
                  <h2 className="text-3xl font-black text-blue-900 uppercase tracking-tighter leading-none">{quizQuestions[currentQuizStep].question}</h2>
                  <div className="grid grid-cols-1 gap-4">
