                      <button 
                        key={i} 
                        onClick={() => handleAnswer(i)} 
                        className="w-full text-left p-6 rounded-2xl border-2 border-slate-100 hover:border-emerald-500 hover:bg-emerald-50 font-bold transition-all text-blue-900"
                      >
                        {opt}
                      </button>
                    ))}
                  </div>
                </div>
              ) : (
                <div>
                  <h1 className="text-4xl font-black text-blue-900 uppercase mb-8 tracking-tighter">{activeLesson.course.modules[activeLesson.moduleIndex]}</h1>
                  {isLessonLoading ? (
                    <div className="animate-pulse space-y-6">
                      <div className="h-6 bg-gray-100 rounded w-1/4"></div>
                      <div className="h-4 bg-gray-100 rounded w-3/4"></div>
                      <div className="h-4 bg-gray-100 rounded w-full"></div>
                      <div className="h-4 bg-gray-100 rounded w-full"></div>
                      <div className="h-4 bg-gray-100 rounded w-5/6"></div>
                    </div>
