                          className="bg-blue-900 text-white px-12 py-5 rounded-2xl font-black uppercase tracking-widest shadow-2xl hover:bg-emerald-600 transition-all disabled:opacity-50"
                        >
                          {isQuizLoading ? <><i className="fas fa-sync fa-spin mr-2"></i> Thinking...</> : 'Take Module Quiz'}
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {selectedCourse && (
        <div className="fixed inset-0 z-[110] bg-blue-900/40 backdrop-blur-sm flex justify-end" onClick={() => setSelectedCourse(null)}>
          <div className="bg-white w-full max-w-md h-full p-10 flex flex-col animate-in slide-in-from-right" onClick={e => e.stopPropagation()}>
            <div className="flex justify-between items-start mb-8">
              <h3 className="text-3xl font-black text-blue-900 uppercase tracking-tighter leading-none">{selectedCourse.title}</h3>
              <button onClick={() => setSelectedCourse(null)} className="text-gray-400 hover:text-red-500"><i className="fas fa-times text-xl"></i></button>
            </div>
            <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest mb-6">Course Syllabus</p>
            <div className="flex-1 overflow-y-auto space-y-4 pr-2 custom-scrollbar">
              {selectedCourse.modules.map((mod, i) => (
                <div key={i} className="p-5 bg-slate-50 rounded-2xl border border-gray-100 font-bold text-blue-900 uppercase text-[10px] tracking-widest flex items-center space-x-4">
                  <span className="w-6 h-6 bg-blue-900 text-white rounded-full flex items-center justify-center shrink-0">{i + 1}</span>
                  <span>{mod}</span>
                </div>
              ))}
            </div>
            <button 
              onClick={() => { handleEnrollInitiation(selectedCourse); setSelectedCourse(null); }}
              className="mt-8 w-full bg-emerald-600 text-white py-5 rounded-3xl font-black uppercase tracking-widest shadow-xl hover:bg-emerald-700 transition-all active:scale-95"
            >
              Enroll Now
            </button>
          </div>
        </div>
      )}
    </section>
  );
};

