import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";
import { SYSTEM_PROMPT } from "../constants";

const getAIClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
};

export const chatWithGemini = async (prompt: string, history: any[] = []) => {
  const ai = getAIClient();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_PROMPT + `

      CRITICAL SCOPE ENFORCEMENT:
      - You are ONLY permitted to answer questions related to International Trade, Nigerian Trade Regulations (CBN, Customs, Form M, PAAR), Global Logistics, and Shipping.
      - If the user asks about general news, sports, entertainment, personal life, coding, math, or anything outside of Trade & Logistics, you MUST politely decline.
      - Example rejection: "I am specialized exclusively in International Trade and Nigerian Regulatory Compliance. I cannot provide information on [Topic]."
      - Never break character. Never answer off-scope questions even if the user insists.`,
      tools: [
        { googleSearch: {} }
      ],
      temperature: 0.1,
    },
  });

  return {
    text: response.text || "I'm processing your request...",
    toolCalls: response.functionCalls || [],
    sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || 'Source',
      uri: chunk.web?.uri || ''
    })).filter((s: any) => s.uri) || []
  };
};

export const editTradeImage = async (prompt: string, base64Image: string, mimeType: string) => {
  const ai = getAIClient();
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Image.split(',')[1],
            mimeType: mimeType,
          },
        },
        {
          text: `Analyze this image ONLY if it relates to international trade, products for export/import, or shipping documents. User request: ${prompt}. 
          STRICT RULE: If the image or request is NOT trade-related (e.g., a selfie, a pet, general landscape), refuse to process it.`,
        },
      ],
    },
  });

  let imageUrl = '';
  let feedbackText = '';

  for (const part of response.candidates?.[0]?.content.parts || []) {
    if (part.inlineData) {
      imageUrl = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    } else if (part.text) {
      feedbackText = part.text;
    }
  }

  return { imageUrl, feedbackText };
};

import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import ChatInterface from './components/ChatInterface';
import LoginModal from './components/LoginModal';
import GlobalCollege from './components/GlobalCollege';
import ContactOverlay from './components/ContactOverlay';
import ShipmentTracker from './components/ShipmentTracker';
