interface ChatInterfaceProps {
  externalPrompt?: string | null;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({ externalPrompt }) => {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: '1',
      role: 'assistant',
      content: "Hello! I'm your DONLEMSONTRADE global consultant. How can I assist with your international trade queries today? You can now attach shipping documents (PDF, Word, Excel) or images for analysis.",
      timestamp: Date.now(),
    }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedFile, setSelectedFile] = useState<{data: string, name: string, type: string} | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading]);

  useEffect(() => {
    if (externalPrompt) {
      handleSend(externalPrompt);
    }
  }, [externalPrompt]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedFile({
          data: reader.result as string,
          name: file.name,
          type: file.type
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const getFileIcon = (mime: string) => {
    if (mime.includes('image')) return 'fa-file-image text-emerald-500';
    if (mime.includes('pdf')) return 'fa-file-pdf text-red-500';
    if (mime.includes('word') || mime.includes('officedocument.word')) return 'fa-file-word text-blue-500';
    if (mime.includes('excel') || mime.includes('officedocument.spreadsheet')) return 'fa-file-excel text-green-600';
    return 'fa-file-alt text-gray-500';
  };

  const handleSend = async (overrideInput?: string) => {
    const messageText = overrideInput || input;
    if (!messageText.trim() && !selectedFile) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: messageText || (selectedFile ? `Analyzing attached file: ${selectedFile.name}` : ""),
      image: selectedFile?.type.includes('image') ? selectedFile.data : undefined,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMessage]);
    if (!overrideInput) setInput('');
    setIsLoading(true);

    try {
      if (selectedFile) {
        const result = await analyzeTradeDocument(
          messageText || `Please analyze this ${selectedFile.name} document and provide trade insights.`,
          selectedFile.data,
          selectedFile.type
        );

        const assistantMessage: Message = {
          id: (Date.now() + 1).toString(),
          role: 'assistant',
          content: result.feedbackText || "I've analyzed the document and provided details.",
          image: result.imageUrl || undefined,
          timestamp: Date.now(),
        };
        setMessages(prev => [...prev, assistantMessage]);
      } else {
        const result = await chatWithGemini(messageText);

        const assistantMessage: Message = {
          id: (Date.now() + 1).toString(),
          role: 'assistant',
          content: result.text,
          sources: result.sources,
          timestamp: Date.now(),
        };
        setMessages(prev => [...prev, assistantMessage]);
      }
    } catch (error) {
      console.error(error);
      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: "I'm sorry, I encountered an error while processing that. Could you try re-uploading the document or re-typing the request?",
        timestamp: Date.now(),
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
      setSelectedFile(null);
    }
  };

  return (
    <div className="flex flex-col h-[600px] bg-white rounded-xl shadow-lg overflow-hidden border border-gray-200">
