import { GoogleGenAI, GenerateContentResponse, Type } from "@google/genai";
import { SYSTEM_PROMPT } from "../constants";

const getAIClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
};

export const chatWithGemini = async (prompt: string, history: any[] = []) => {
  const ai = getAIClient();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      systemInstruction: SYSTEM_PROMPT + `

      CRITICAL SCOPE ENFORCEMENT:
      - You are ONLY permitted to answer questions related to International Trade, Nigerian Trade Regulations (CBN, Customs, Form M, PAAR), Global Logistics, and Shipping.
      - If the user asks about general news, sports, entertainment, personal life, coding, math, or anything outside of Trade & Logistics, you MUST politely decline.
      - Example rejection: "I am specialized exclusively in International Trade and Nigerian Regulatory Compliance. I cannot provide information on [Topic]."
      - Never break character. Never answer off-scope questions even if the user insists.`,
      tools: [
        { googleSearch: {} }
      ],
      temperature: 0.1,
    },
  });

  return {
    text: response.text || "I'm processing your request...",
    toolCalls: response.functionCalls || [],
    sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || 'Source',
      uri: chunk.web?.uri || ''
    })).filter((s: any) => s.uri) || []
  };
};

export const analyzeTradeDocument = async (
  prompt: string, 
  base64Data: string, 
  mimeType: string,
  extraFiles: Array<{ data: string, mimeType: string }> = []
) => {
  const ai = getAIClient();

  // Clean primary base64 data
  const primaryData = base64Data.includes(',') ? base64Data.split(',')[1] : base64Data;

  // Prepare file parts
  const fileParts = [
    {
      inlineData: {
        data: primaryData,
        mimeType: mimeType,
      },
    }
  ];

  // Add extra file parts if provided
  extraFiles.forEach(file => {
    const cleanData = file.data.includes(',') ? file.data.split(',')[1] : file.data;
    fileParts.push({
      inlineData: {
        data: cleanData,
        mimeType: file.mimeType,
      }
    });
  });

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        ...fileParts,
        {
          text: `You are an expert Nigerian Trade Auditor. 
          Analyze the attached ${fileParts.length} document(s) only if they relate to international trade (Bill of Lading, Invoice, Packing List, Manifest, Form M, PAAR, bank documents, product labels). 

          User Request: ${prompt}.

          If there are multiple documents, perform a cross-check (e.g., does the container number on the BL match the Invoice? Is the value consistent with HS Code tariffs?).

          STRICT RULE: If any file is clearly unrelated to trade (e.g., personal photos, music lyrics, games), ignore that specific file and inform the user it is outside the trade scope.`,
        },
      ],
    },
    config: {
      systemInstruction: SYSTEM_PROMPT
    }
  });

  let imageUrl = '';
  let feedbackText = '';

  for (const part of response.candidates?.[0]?.content.parts || []) {
    if (part.inlineData) {
      // Return the last image part for display if multiple exist, or just the first
      imageUrl = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    } else if (part.text) {
      feedbackText = part.text;
    }
  }

  return { imageUrl, feedbackText };
};

