      content: messageText || (selectedFiles.length > 0 ? `Analyzing ${selectedFiles.length} attached document(s): ${selectedFiles.map(f => f.name).join(', ')}` : ""),
      image: firstImage,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMessage]);
    if (!overrideInput) setInput('');
    setIsLoading(true);

    const currentFiles = [...selectedFiles];
    setSelectedFiles([]); // Clear queue immediately

    try {
      if (currentFiles.length > 0) {
        // Handle multiple files
        // If multiple images are present, we pass them all to the service
        // For simplicity in this UI, we only show one response but the backend processes all
        const result = await analyzeTradeDocument(
          messageText || `Analyze these ${currentFiles.length} documents for trade compliance.`,
          currentFiles[0].data, // Primary data
          currentFiles[0].type,
          currentFiles.slice(1).map(f => ({ data: f.data, mimeType: f.type })) // Additional parts
